window.MIT_COURSE_PARTS=window.MIT_COURSE_PARTS||[];window.MIT_COURSE_PARTS.push([{"code":"6.C27","title":"Computational Imaging: Physics and Algorithms","level":"U","description":"Explores the contemporary computational understanding of imaging: encoding information about a physical object onto a form of radiation, transferring the radiation through an imaging system, converting it to a digital signal, and computationally decoding and presenting the information to the user. Introduces a unified formulation of computational imaging systems as a three-round 'learning spiral': the first two rounds describe the physical and algorithmic parts in two exemplary imaging systems. The third round involves a class project on an imaging system chosen by students. Undergraduate and graduate versions share lectures but have different recitations. Involves optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.C27"},{"code":"6.C40","title":"Ethics of Computing","level":"U","description":"Explores ethical questions raised by the potentially transformative power of computing technologies. Topics include: lessons from the history of transformative technologies; the status of property and privacy rights in the digital realm; effective accelerationism, AI alignment, and existential risk; algorithmic bias and algorithmic fairness; and free speech, disinformation, and polarization on online platforms.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:00","room":"32-155"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"56-180"},{"days":["F"],"start":"11:00","end":"12:00","room":"56-180"},{"days":["F"],"start":"12:00","end":"13:00","room":"56-180"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.C40"},{"code":"6.C57","title":"Optimization Methods","level":"G","description":"Introduction to the methods and applications of optimization. Topics include linear optimization, duality, non-linear optimization, integer optimization, and optimization under uncertainty. Instruction provided in modeling techniques to address problems arising in practice, mathematical theory to understand the structure of optimization problems, computational algorithms to solve complex optimization problems, and practical applications. Covers several examples and in-depth case studies based on real-world data to showcase impactful applications of optimization across management and engineering. Computational exercises based on the Julia-based programming language JuMP. Includes a term project. Basic competency in computational programming and linear algebra recommended. Students taking graduate version complete additional assignments. This subject was previously listed as 15.093/6.7200/IDS.200. One section primarily reserved for Sloan students; check syllabus for details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-345"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E25-111"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-345"},{"days":["F"],"start":"13:00","end":"14:00","room":"45-230"},{"days":["F"],"start":"14:00","end":"15:00","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.C57"},{"code":"6.C571","title":"Optimization Methods","level":"U","description":"Introduction to the methods and applications of optimization. Topics include linear optimization, duality, non-linear optimization, integer optimization, and optimization under uncertainty. Instruction provided in modeling techniques to address problems arising in practice, mathematical theory to understand the structure of optimization problems, computational algorithms to solve complex optimization problems, and practical applications. Covers several examples and in-depth case studies based on real-world data to showcase impactful applications of optimization across management and engineering. Computational exercises based on the Julia-based programming language JuMP. Includes a term project. Basic competency in computational programming and linear algebra recommended. Students taking graduate version complete additional assignments. This subject was previously listed as 6.7201.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-345"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E25-111"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-345"},{"days":["F"],"start":"13:00","end":"14:00","room":"45-230"},{"days":["F"],"start":"14:00","end":"15:00","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.C571"},{"code":"6.C67","title":"Computational Imaging: Physics and Algorithms","level":"G","description":"Contemporary understanding of imaging is computational: encoding onto a form of radiation the information about a physical object, transferring the radiation through the imaging system, converting it to a digital signal, and computationally decoding and presenting the information to the user. This class introduces a unified formulation of computational imaging systems as a three-round 'learning spiral': the first two rounds, instructors describe the physical and algorithmic parts in two exemplary imaging systems. The third round, students conduct themselves as the class project on an imaging system of their choice. The undergraduate and graduate versions share lectures but have different recitations. Throughout the term, we also conduct optional 'clinics' to even out background knowledge of linear algebra, optimization, and computational imaging-related programming best practices for students of diverse disciplinary backgrounds.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"24-121"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.C67"},{"code":"6.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.EPE"},{"code":"6.S057","title":"Special Subject in Electrical Engineering and Computer Science","level":"U","description":"Covers subject matter not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S057"},{"code":"6.S630","title":"Special Subject in Engineering Leadership","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult the Gordon Engineering Leadership Program or Riccio Graduate Engineering Leadership Program to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:30","end":"18:30","room":"35-434"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S630"},{"code":"6.S660","title":"Special Subject in Engineering Leadership","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult the Gordon Engineering Leadership Program or Riccio Graduate Engineering Leadership Program to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"36-112"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S660"},{"code":"6.S950","title":"Special Subject in Electrical Engineering and Computer Science","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:30","end":"16:00","room":"37-212"}]},{"type":"Lab","options":[{"days":["R"],"start":"14:30","end":"16:00","room":"32-044"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S950"},{"code":"6.S951","title":"Special Subject in Electrical Engineering and Computer Science","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"37-212"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S951"},{"code":"6.S952","title":"Special Subject in Electrical Engineering and Computer Science","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"36-144"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S952"},{"code":"6.S953","title":"Special Subject in Electrical Engineering and Computer Science","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S953"},{"code":"6.S964","title":"Special Studies: EECS","level":"G","description":"Opportunity for study of graduate-level topics related to electrical engineering and computer science but not included elsewhere in the curriculum. Registration under this subject normally used for situations involving small study groups. Normal registration is for 12 units. Registration subject to approval of professor in charge.  Consult the department for details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-257"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"4-265"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S963-6.S967"},{"code":"6.S974","title":"Special Subject in Electrical Engineering and Computer Science","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S974"},{"code":"6.S978","title":"Special Subject in Electrical Engineering and Computer Science","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"11:00","end":"13:00","room":"32-144"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S978"},{"code":"6.S979","title":"Special Subject in Electrical Engineering and Computer Science","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"11:00","end":"14:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S979"},{"code":"6.S980","title":"Special Subject in Electrical Engineering and Computer Science","level":"G","description":"Covers subject matter not offered in the regular curriculum. Consult department to learn of offerings for a particular term.","groups":[{"type":"Lecture","options":[{"days":["R","F"],"start":"13:00","end":"14:30","room":"24-115"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.S980"},{"code":"6.UAR","title":"Seminar in Undergraduate Advanced Research","level":"U","description":"Instruction in effective undergraduate research, including choosing and developing a research topic, surveying previous work and publications, research topics in EECS and the School of Engineering, industry best practices, design for robustness, technical presentation, authorship and collaboration, and ethics. Students engage in extensive written and oral communication exercises, in the context of an approved advanced research project. A total of 12 units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult EECS SuperUROP website for more information.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:00","end":"17:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.UAR"},{"code":"6.UAT","title":"Oral Communication","level":"U","description":"Provides instruction in aspects of effective technical oral presentations and exposure to communication skills useful in a workplace setting. Students create, give and revise a number of presentations of varying length targeting a range of different audiences.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"36-156"}]}],"url":"http://student.mit.edu/catalog/m6e.html#6.UAT"},{"code":"7.002","title":"Fundamentals of Experimental Molecular Biology","level":"U","description":"Introduces the experimental concepts and methods of molecular biology. Covers basic principles of experimental design and data analysis, with an emphasis on the acquisition of practical laboratory experience. Satisfies 6 units of Institute Laboratory credit. Satisfies biology laboratory credit for pre-health professions. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"13:00","end":"14:30","room":"68-181"}]},{"type":"Lab","options":[{"days":["W"],"start":"13:00","end":"16:30","room":"68-074"},{"days":["F"],"start":"13:00","end":"16:30","room":"68-074"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.002"},{"code":"7.003","title":"Applied Molecular Biology Laboratory","level":"U","description":"Laboratory-based exploration of modern experimental molecular biology. Specific experimental system studied may vary from term to term, depending on instructor. Emphasizes concepts of experimental design, data analysis and communication in biology and how these concepts are applied in the biotechnology industry. Satisfies 6 units of Institute Laboratory credit. Enrollment limited; admittance may be controlled by lottery.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:00","room":"68-181"}]},{"type":"Lab","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"68-074"}]},{"type":"Recitation","options":[{"days":["T"],"start":"11:00","end":"12:30","room":"68-121"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.003"},{"code":"7.012","title":"Introductory Biology","level":"U","description":"Discusses core principles including: chemical bonding and molecular interactions, protein structure/function and basic thermodynamics, how information flows in the cell, genetics, tools for studying and manipulating genetic material, sequencing, cell biology, evolution, and how the body fights off harmful disease-causing agents. 7.012 synthesizes the core principles into a coherent whole by following the scientific narrative of recent major advances in medicine. Students the complete a final project, with a video and written components, in which they explore an additional medical breakthrough that they choose from a set of options. Enrollment limited to seating capacity of classroom. Admittance may be controlled by lottery.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"10-250"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"09:00","end":"10:00","room":"26-204"},{"days":["T","R"],"start":"10:00","end":"11:00","room":"26-204"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"26-204"},{"days":["T","R"],"start":"12:00","end":"13:00","room":"26-204"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"26-204"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"26-204"},{"days":["T","R"],"start":"15:00","end":"16:00","room":"26-204"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.012"},{"code":"7.015","title":"Introductory Biology","level":"U","description":"Discusses the core principles including: chemical bonding and molecular interactions, protein structure/function and basic thermodynamics, how information flows in the cell, genetics, tools for studying and manipulating genetic material, sequencing, cell biology, evolution, and how the body fights off harmful disease-causing agents. 7.015 presents the core principles through the lens of modern, trending topics in biology. Students read popular science articles and discuss social and ethical issues surrounding contemporary biology. Limited to 70; admittance may be controlled by lottery.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-370"}]},{"type":"Recitation","options":[{"days":["W","F"],"start":"10:00","end":"11:00","room":"38-166"},{"days":["W","F"],"start":"11:00","end":"12:00","room":"38-166"},{"days":["W","F"],"start":"12:00","end":"13:00","room":"38-166"},{"days":["W","F"],"start":"13:00","end":"14:00","room":"36-372"},{"days":["W","F"],"start":"14:00","end":"15:00","room":"36-372"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.015"},{"code":"7.02","title":"Introduction to Experimental Biology and Communication","level":"U","description":"Introduction to the experimental concepts and methods of molecular biology, biochemistry, and genetic analysis. Emphasis on experimental design, critical data analysis, and the development of written communications skills. 12 units may be applied to the General Institute Laboratory Requirement. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"4-370"}]},{"type":"Lab","options":[{"days":["T","R"],"start":"13:00","end":"17:00","room":"68-074"}]},{"type":"Recitation","options":[{"days":["M"],"start":"09:00","end":"11:00","room":"68-121"},{"days":["M"],"start":"13:00","end":"15:00","room":"68-121"},{"days":["M"],"start":"13:00","end":"15:00","room":"56-169"},{"days":["T"],"start":"09:00","end":"11:00","room":"66-148"},{"days":["W"],"start":"13:00","end":"15:00","room":"68-156"},{"days":["W"],"start":"09:00","end":"11:00","room":"68-121"},{"days":["M"],"start":"14:30","end":"16:30","room":"68-181"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.02"},{"code":"7.03","title":"Genetics","level":"U","description":"The principles of genetics with application to the study of biological function at the level of molecules, cells, and multicellular organisms, including humans. Structure and function of genes, chromosomes, and genomes. Biological variation resulting from recombination, mutation, and selection. Population genetics. Use of genetic methods to analyze protein function, gene regulation, and inherited disease.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"11:00","end":"12:00","room":"4-370"}]},{"type":"Recitation","options":[{"days":["M"],"start":"14:00","end":"15:00","room":"26-204"},{"days":["M"],"start":"15:00","end":"16:00","room":"26-204"},{"days":["T"],"start":"13:00","end":"14:00","room":"26-322"},{"days":["T"],"start":"14:00","end":"15:00","room":"26-322"},{"days":["W"],"start":"12:00","end":"13:00","room":"26-322"},{"days":["W"],"start":"13:00","end":"14:00","room":"26-322"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.03"},{"code":"7.06","title":"Cell Biology","level":"U","description":"Presents the biology of cells of higher organisms. Studies the structure, function, and biosynthesis of cellular membranes and organelles; cell growth and oncogenic transformation; transport, receptors, and cell signaling; the cytoskeleton, the extracellular matrix, and cell movements; cell division and cell cycle; functions of specialized cell types. Emphasizes the current molecular knowledge of cell biological processes as well as the genetic, biochemical, and other experimental approaches that resulted in these discoveries.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"4-270"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"26-204"},{"days":["F"],"start":"11:00","end":"12:00","room":"26-204"},{"days":["F"],"start":"12:00","end":"13:00","room":"26-204"},{"days":["F"],"start":"13:00","end":"14:00","room":"26-204"},{"days":["F"],"start":"14:00","end":"15:00","room":"26-204"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.06"},{"code":"7.18","title":"Topics in Experimental Biology","level":"U","description":"Independent experimental study under the direction of a member of the Biology Department faculty. Allows students with a strong interest in independent research to fulfill the project laboratory requirement for the Biology Department Program in the context of a research laboratory at MIT. The research must be conducted on the MIT campus and be a continuation of a previous 12-unit UROP project or full-time work over the summer. Written and oral presentation of the research results is required. Journal club discussions are used to help students evaluate and write scientific papers. Instruction and practice in written and oral communication is provided. Permission of the faculty research supervisor and the Biology Education Office must be obtained in advance.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"16:00","room":"68-121"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.18"},{"code":"7.19","title":"Communication in Experimental Biology","level":"U","description":"Students carry out independent literature research. Journal club discussions are used to help students evaluate and write scientific papers. Instruction and practice in written and oral communication is provided.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"16:00","room":"68-121"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.19"},{"code":"7.20","title":"Human Physiology","level":"U","description":"Comprehensive exploration of human physiology, emphasizing the molecular basis and applied aspects of organ function and regulation in health and disease. Includes a review of cell structure and function, as well as the mechanisms by which the endocrine and nervous systems integrate cellular metabolism. Special emphasis on examining the cardiovascular, pulmonary, gastrointestinal, renal, reproductive, and muscular skeletal systems, as well as liver function, drug metabolism, and pharmacogenetics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"11:00","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["T"],"start":"19:30","end":"20:30","room":"26-328"},{"days":["W"],"start":"11:00","end":"12:00","room":"26-328"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.20"},{"code":"7.30","title":"Fundamentals of Ecology","level":"U","description":"Fundamentals of ecology, considering Earth as an integrated dynamic living system. Coevolution of the biosphere and geosphere, biogeochemical cycles, metabolic diversity, primary productivity, competition and the niche, trophic dynamics and food webs, population growth and limiting factors. Population modeling, global carbon cycle, climate change, geoengineering, theories of resource competition and mutualism, allometric scaling, ecological genomics, niche theory, human population growth. Applied ecology.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"48-316"}]},{"type":"Recitation","options":[{"days":["M"],"start":"15:00","end":"16:00","room":"48-316"},{"days":["F"],"start":"11:00","end":"12:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.30"},{"code":"7.30A","title":"Fundamentals of Ecology I","level":"U","description":"Fundamentals of ecology, considering Earth as an integrated dynamic living system. Coevolution of the biosphere and geosphere, biogeochemical cycles, metabolic diversity, primary productivity, competition and the niche, trophic dynamics and food webs, population growth and limiting factors. Combination of 1.018A and 1.018B counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"1-242"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"48-316"},{"days":["R"],"start":"16:00","end":"17:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.30A"},{"code":"7.30B","title":"Fundamentals of Ecology II","level":"U","description":"Advanced topics in Ecology. Population modeling, global carbon cycle, climate change, geoengineering, theories of resource competition and mutualism, allometric scaling, ecological genomics, niche theory, human population growth. Applied ecology. Combination of 1.018A and 1.018B counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"1-242"}]},{"type":"Recitation","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"48-316"},{"days":["R"],"start":"16:00","end":"17:00","room":"48-316"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.30B"},{"code":"7.32","title":"Systems Biology","level":"U","description":"Introduction to cellular and population-level systems biology with an emphasis on synthetic biology, modeling of genetic networks, cell-cell interactions, and evolutionary dynamics.  Cellular systems include genetic switches and oscillators, network motifs, genetic network evolution, and cellular decision-making.  Population-level systems include models of pattern formation, cell-cell communications, and evolutionary systems biology.  Students taking graduate version explore the subject in more depth.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-159"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.32"},{"code":"7.341","title":"Advanced Undergraduate Seminar","level":"U","description":"Seminars covering topics of current interest in biology with a focus on how to understand experimental methods and design and how to critically read the primary research literature. Small class size facilitates discussions and interactions with an active research scientist. Students visit research laboratories to see firsthand how biological research is conducted. Contact Biology Education Office for topics.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"10:00","end":"12:00","room":"1-273"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.340-7.344"},{"code":"7.342","title":"Advanced Undergraduate Seminar","level":"U","description":"Seminars covering topics of current interest in biology with a focus on how to understand experimental methods and design and how to critically read the primary research literature. Small class size facilitates discussions and interactions with an active research scientist. Students visit research laboratories to see firsthand how biological research is conducted. Contact Biology Education Office for topics.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"11:00","end":"13:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.340-7.344"},{"code":"7.36","title":"The CRISPR Revolution:  Engineering the Genome for Basic Science and Clinical Medicine","level":"U","description":"Provides a conceptual and technical understanding of genome editing systems and their research and clinical applications. Focuses on fundamental CRISPR biology in bacteria, methodologies for manipulating the genome with CRISPR, and the application of genome engineering in research and medicine. Combines lectures and literature discussions with critical analysis and assigned readings, with the goal of better understanding how key discoveries were made and how these are applied in the real work. Class work includes brief writing assignments as well as a final research proposal and scientific presentation. Students taking the graduate version explore the subject in greater depth, in part through additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:30","end":"13:00","room":""}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.36"},{"code":"7.371","title":"Biological and Engineering Principles Underlying Novel Biotherapeutics","level":"U","description":"Covers biological and bioengineering principles underlying the development and therapeutic use of recombinant proteins and immune cells. Special attention to monoclonal antibodies and engineered immune system cells as therapeutics; protein- and glyco- engineering to enhance protein function; protein pharmacology and delivery; nucleic acid- based biotherapeutics; generation of functional cells and tissues from embryonic stem cells and iPS cells; and immune cell-cancer cell interactions in cancer immunotherapy.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"17:00","room":""}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.371"},{"code":"7.38","title":"Design Principles of Biological Systems","level":"U","description":"Introduces students to biological control mechanisms governing decision-making and tools to decipher, model, and perturb these mechanisms. Systems presented include signal transduction, cell cycle control, developmental biology, and the immune system. These systems provide examples of feedback and feedforward control, oscillators, kinetic proofreading, spatial and temporal averaging, and pattern formation. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:30","room":"4-265"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.38"},{"code":"7.430","title":"Topics in Quantitative Marine Science","level":"G","description":"Lectures and discussions on quantitative marine ecology.  Topics vary from year to year.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:30","end":"16:00","room":"WHOI CAMPUS"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.430"},{"code":"7.433","title":"Topics in Biological Oceanography","level":"G","description":"Lectures and discussions on biological oceanography. Topics vary from year to year.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:30","end":"16:00","room":"WHOI CAMPUS"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.433"},{"code":"7.45","title":"The Hallmarks of Cancer","level":"U","description":"Provides a comprehensive introduction to the fundamentals of cancer biology and cancer treatment. Topics include cancer genetics, genomics, and epigenetics; familial cancer syndromes; signal transduction, cell cycle control, and apoptosis; cancer metabolism; stem cells and cancer; metastasis; cancer immunology and immunotherapy; conventional and molecularly-targeted therapies; and early detection and prevention. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"32-155"}]},{"type":"Recitation","options":[{"days":["R"],"start":"19:00","end":"20:00","room":"26-314"},{"days":["F"],"start":"11:00","end":"12:00","room":"26-314"},{"days":["F"],"start":"12:00","end":"13:00","room":"26-314"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.45"},{"code":"7.46","title":"Building with Cells","level":"U","description":"Focuses on fundamental principles of developmental biology by which cells build organs and organisms. Analyzes the pivotal role of stem cells in tissue maintenance or repair, and in treatment of disease. Explores how to integrate this knowledge with engineering tools to construct functional tissue structures. Students taking graduate version complete additional assignments","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.46"},{"code":"7.492","title":"Methods and Problems in Microbiology","level":"G","description":"Students will read and discuss primary literature covering key areas of microbial research with emphasis on methods and approaches used to understand and manipulate microbes. Preference to first-year Microbiology and Biology students.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"15:30","room":"68-156"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.492"},{"code":"7.493","title":"Microbial Genetics and Evolution","level":"G","description":"Covers aspects of microbial genetic and genomic analyses, central dogma, horizontal gene transfer, and evolution.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:30","end":"14:30","room":"66-160"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"66-156"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.493"},{"code":"7.50","title":"Method and Logic in Molecular Biology","level":"G","description":"Logic, experimental design and methods in biology, using discussions of the primary literature to discern the principles of biological investigation in making discoveries and testing hypotheses. In collaboration with faculty, students also apply those principles to generate a potential research project, presented in both written and oral form. Limited to Course 7 graduate students.","groups":[{"type":"Recitation","options":[{"days":["M"],"start":"15:00","end":"18:00","room":""}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.50"},{"code":"7.51","title":"Principles of Biochemical Analysis","level":"G","description":"Principles of protein biochemistry, emphasizing structure, equilibrium studies, kinetics, and experimental design. Topics include macromolecular binding and specificity, allosteric systems, mechanisms of inhibition, enzyme principles, single-molecule studies, structure-function relationships, molecular evolution, and library methods. Case studies examine mechanisms of transcription factors, kinases, molecular machines, and other proteins.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"09:00","end":"10:30","room":"56-114"}]},{"type":"Recitation","options":[{"days":["T"],"start":"14:30","end":"15:30","room":"56-114"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.51"},{"code":"7.52","title":"Genetics for Graduate Students","level":"G","description":"Principles and approaches of genetic analysis, including Mendelian inheritance and prokaryotic genetics, yeast genetics, developmental genetics, neurogenetics, and human genetics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:30","room":"56-154"}]},{"type":"Recitation","options":[{"days":["W"],"start":"15:30","end":"16:30","room":"66-144"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.52"},{"code":"7.540","title":"Advances in Chemical Biology","level":"G","description":"Introduction to current research at the interface of chemistry, biology, and bioengineering. Topics include imaging of biological processes, metabolic pathway engineering, protein engineering, mechanisms of DNA damage, RNA structure and function, macromolecular machines, protein misfolding and disease, metabolomics, and methods for analyzing signaling network dynamics. Lectures are interspersed with class discussions and student presentations based on current literature.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.540"},{"code":"7.61","title":"Eukaryotic Cell Biology: Principles and Practice","level":"G","description":"Emphasizes methods and logic used to analyze structure and function of eukaryotic cells in diverse systems (e.g., yeast, fly, worm, mouse, human; development, stem cells, neurons). Combines lectures and in-depth roundtable discussions of literature readings with the active participation of faculty experts. Focuses on membranes (structure, function, traffic), organelles, the cell surface, signal transduction, cytoskeleton, cell motility and extracellular matrix. Ranges from basic studies to applications to human disease, while stressing critical analysis of experimental approaches. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"15:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.61"},{"code":"7.65","title":"Molecular and Cellular Neuroscience Core I","level":"G","description":"Survey and primary literature review of selected major topic areas in molecular and cellular neurobiology. Covers nervous system development, axonal pathfinding, synapse formation and function, synaptic plasticity, ion channels and receptors, cellular neurophysiology, glial cells, sensory transduction, and relevant examples in human disease. Includes lectures and weekly paper write-ups, together with student presentations and discussion of primary literature. A final two-page research write-up is also due at the end of the term.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"46-4062"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.65"},{"code":"7.81","title":"Systems Biology","level":"G","description":"Introduction to cellular and population-level systems biology with an emphasis on synthetic biology, modeling of genetic networks, cell-cell interactions, and evolutionary dynamics.  Cellular systems include genetic switches and oscillators, network motifs, genetic network evolution, and cellular decision-making.  Population-level systems include models of pattern formation, cell-cell communication, and evolutionary systems biology. Students taking graduate version explore the subject in more depth.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-159"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.81"},{"code":"7.83","title":"Design Principles of Biological Systems","level":"G","description":"Introduces students to biological control mechanisms governing decision-making and tools to decipher, model, and perturb these mechanisms. Systems presented include signal transduction, cell cycle control, developmental biology, and the immune system. These systems provide examples of feedback and feedforward control, oscillators, kinetic proofreading, spatial and temporal averaging, and pattern formation. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"14:30","room":"4-265"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.83"},{"code":"7.85","title":"The Hallmarks of Cancer","level":"G","description":"Provides a comprehensive introduction to the fundamentals of cancer biology and cancer treatment. Topics include cancer genetics, genomics, and epigenetics; familial cancer syndromes; signal transduction, cell cycle control, and apoptosis; cancer metabolism; stem cells and cancer; metastasis; cancer immunology and immunotherapy; conventional and molecularly-targeted therapies; and early detection and prevention. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"32-155"}]},{"type":"Recitation","options":[{"days":["R"],"start":"19:00","end":"20:00","room":"26-314"},{"days":["F"],"start":"11:00","end":"12:00","room":"26-314"},{"days":["F"],"start":"12:00","end":"13:00","room":"26-314"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.85"},{"code":"7.86","title":"Building with Cells","level":"G","description":"Focuses on fundamental principles of developmental biology by which cells build organs and organisms. Analyzes the pivotal role of stem cells in tissue maintenance or repair, and in treatment of disease. Explores how to integrate this knowledge with engineering tools to construct functional tissue structures. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.86"},{"code":"7.89","title":"Topics in Computational and Systems Biology","level":"G","description":"Seminar based on research literature. Papers covered are selected to illustrate important problems and varied approaches in the field of computational and systems biology, and to provide students a framework from which to evaluate new developments. Preference to first-year CSB PhD students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"11:00","end":"13:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.89"},{"code":"7.91","title":"The CRISPR Revolution:  Engineering the Genome for Basic Science and Clinical Medicine","level":"G","description":"Provides a conceptual and technical understanding of genome editing systems and their research and clinical applications. Focuses on fundamental CRISPR biology in bacteria, methodologies for manipulating the genome with CRISPR, and the application of genome engineering in research and medicine. Combines lectures and literature discussions with critical analysis and assigned readings, with the goal of better understanding how key discoveries were made and how these are applied in the real work. Class work includes brief writing assignments as well as a final research proposal and scientific presentation. Students taking the graduate version explore the subject in greater depth, in part through additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:30","end":"13:00","room":""}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.91"},{"code":"7.930","title":"Research Experience in Biopharma","level":"G","description":"Provides exposure to industrial science and develops skills necessary for success in such an environment. Under the guidance of an industrial mentor, students participate in on-site research at a local biopharmaceutical company where they observe and participate in industrial science. Serves as a real-time case study to internalize the factors that shape R&D in industry, including the purpose and scope of a project, key decision points in the past and future, and strategies for execution. Students utilize company resources and work with a scientific team to contribute to the goals of their assigned project; they then present project results to the company and class, emphasizing the logic that dictated their work and their ideas for future directions. Lecture component focuses on professional development. Enrollment may be limited based on availability of internship opportunities. Open to MIT students only.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"11:00","end":"12:00","room":"16-220"}]}],"url":"http://student.mit.edu/catalog/m7a.html#7.930"},{"code":"8.006","title":"Exploring Physics Using Python","level":"U","description":"Reviews and reinforces 6.100L topics, making connections and studying interesting physical systems (from abstract knowledge of concepts to modeling, coding, and evaluating results) that are relevant to physicists. Classes are active and interactive. Students apply programming skills to introductory physics problems and explore the role of simulations on physics. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"2-147"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.006"},{"code":"8.01","title":"Physics I","level":"U","description":"Introduces classical mechanics. Space and time: straight-line kinematics; motion in a plane; forces and static equilibrium; particle dynamics, with force and conservation of momentum; relative inertial frames and non-inertial force; work, potential energy and conservation of energy; kinetic theory and the ideal gas; rigid bodies and rotational dynamics; vibrational motion; conservation of angular momentum; central force motions; fluid mechanics. Subject taught using the TEAL (Technology-Enabled Active Learning) format which features students working in groups of three, discussing concepts, solving problems, and doing table-top experiments with the aid of computer data acquisition and analysis.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:00","end":"10:30","room":"26-152"},{"days":["M","W"],"start":"10:30","end":"12:00","room":"26-152"},{"days":["M","W"],"start":"13:00","end":"14:30","room":"26-152"},{"days":["M","W"],"start":"15:00","end":"16:30","room":"26-152"},{"days":["T","R"],"start":"09:00","end":"10:30","room":"26-152"},{"days":["T","R"],"start":"11:00","end":"12:30","room":"26-152"},{"days":["T","R"],"start":"13:00","end":"14:30","room":"26-152"},{"days":["T","R"],"start":"15:00","end":"16:30","room":"26-152"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.01"},{"code":"8.012","title":"Physics I","level":"U","description":"Elementary mechanics, presented in greater depth than in 8.01. Newton's laws, concepts of momentum, energy, angular momentum, rigid body motion, and non-inertial systems. Uses elementary calculus freely; concurrent registration in a math subject more advanced than 18.01 is recommended. In addition to covering the theoretical subject matter, students complete a small experimental project of their own design. First-year students admitted via AP or Math Diagnostic for Physics Placement results.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"10:30","room":"6-120"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"26-204"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"26-204"},{"days":["M","W"],"start":"13:00","end":"14:00","room":"26-314"},{"days":["M","W"],"start":"14:00","end":"15:00","room":"26-314"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.012"},{"code":"8.01L","title":"Physics I","level":"U","description":"Introduction to classical mechanics (see description under 8.01). Includes components of the TEAL (Technology-Enabled Active Learning) format. Material covered over a longer interval so that the subject is completed by the end of the IAP. Substantial emphasis given to reviewing and strengthening necessary mathematics tools, as well as basic physics concepts and problem-solving skills. Content, depth, and difficulty is otherwise identical to that of 8.01. The subject is designated as 8.01 on the transcript.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"32-082"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.01L"},{"code":"8.02","title":"Physics II","level":"U","description":"Introduction to electromagnetism and electrostatics: electric charge, Coulomb's law, electric structure of matter; conductors and dielectrics. Concepts of electrostatic field and potential, electrostatic energy. Electric currents, magnetic fields and Ampere's law. Magnetic materials. Time-varying fields and Faraday's law of induction. Basic electric circuits. Electromagnetic waves and Maxwell's equations. Subject taught using the TEAL (Technology Enabled Active Learning) studio format which utilizes small group interaction and current technology to help students develop intuition about, and conceptual models of, physical phenomena.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"09:00","end":"10:30","room":"32-082"},{"days":["M","W"],"start":"10:30","end":"12:00","room":"32-082"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.02"},{"code":"8.021","title":"Physics II","level":"U","description":"Introduction to electromagnetism and electrostatics: electric charge, Coulomb's law, electric structure of matter; conductors and dielectrics. Concepts of electrostatic field and potential, electrostatic energy. Electric currents, magnetic fields and Ampere's law. Magnetic materials. Time-varying fields and Faraday's law of induction. Basic electric circuits. Electromagnetic waves and Maxwell's equations. Designed for students with previous experience in 8.02; the subject is designated as 8.02 on the transcript. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"35-310"}]},{"type":"Lab","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"26-210"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:00","room":"26-204"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.021"},{"code":"8.022","title":"Physics II","level":"U","description":"Parallel to 8.02, but more advanced mathematically. Some knowledge of vector calculus assumed. Maxwell's equations, in both differential and integral form. Electrostatic and magnetic vector potential. Properties of dielectrics and magnetic materials. In addition to the theoretical subject matter, several experiments in electricity and magnetism are performed by the students in the laboratory.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"6-120"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"2-143"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"2-143"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.022"},{"code":"8.03","title":"Physics III","level":"U","description":"Mechanical vibrations and waves; simple harmonic motion, superposition, forced vibrations and resonance, coupled oscillations, and normal modes; vibrations of continuous systems; reflection and refraction; phase and group velocity. Optics; wave solutions to Maxwell's equations; polarization; Snell's Law, interference, Huygens's principle, Fraunhofer diffraction, and gratings.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:30","end":"13:00","room":"6-120"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"10:00","end":"11:00","room":"26-314"},{"days":["M","W"],"start":"11:00","end":"12:00","room":"26-314"},{"days":["M","W"],"start":"13:00","end":"14:00","room":"26-142"},{"days":["M","W"],"start":"14:00","end":"15:00","room":"26-142"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.03"},{"code":"8.033","title":"Relativity","level":"U","description":"Einstein's postulates; consequences for simultaneity, time dilation, length contraction, and clock synchronization; Lorentz transformation; relativistic effects and paradoxes; Minkowski diagrams; invariants and four-vectors; momentum, energy, and mass; particle collisions. Relativity and electricity; Coulomb's law; magnetic fields. Brief introduction to Newtonian cosmology. Introduction to some concepts of general relativity; principle of equivalence. The Schwarzchild metric; gravitational red shift; particle and light trajectories; geodesics; Shapiro delay.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"6-120"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"34-304"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"34-303"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.033"},{"code":"8.041","title":"Quantum Physics I","level":"U","description":"Blended version of 8.04 using a combination of online and in-person instruction. Covers the experimental basis of quantum physics: Mach-Zender interferometers, the photoelectric effect, Compton scattering, and de Broglie waves. Heisenberg uncertainty principle and momentum space. Introduction to wave mechanics: Schroedinger's equation, probability amplitudes, and wave packets. Stationary states and the spectrum of one-dimensional potentials, including the variational principle, the Hellmann-Feynman lemma, the virial theorem, and the harmonic oscillator. Basics of angular momentum, central potentials, and the hydrogen atom. Introduction to the Stern-Gerlach experiment, spin one-half, spin operators, and spin states.","groups":[{"type":"Recitation","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"4-231"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.041"},{"code":"8.05","title":"Quantum Physics II","level":"U","description":"Vector spaces, linear operators, and matrix representations.  Inner products and adjoint operators. Commutator identities. Dirac's Bra-kets. Uncertainty principle and energy-time version. Spectral theorem and complete set of commuting observables. Schrodinger and Heisenberg pictures.  Axioms of quantum mechanics. Coherent states and nuclear magnetic resonance. Multiparticle states and tensor products. Quantum teleportation, EPR and Bell inequalities. Angular momentum and central potentials. Addition of angular momentum. Density matrices, pure and mixed states, decoherence.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:30","end":"14:00","room":"6-120"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"10:00","end":"11:00","room":"4-149"},{"days":["T","R"],"start":"11:00","end":"12:00","room":"4-145"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"26-314"},{"days":["T","R"],"start":"14:00","end":"15:00","room":"26-314"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.05"},{"code":"8.07","title":"Electromagnetism II","level":"U","description":"Survey of basic electromagnetic phenomena: electrostatics, magnetostatics; electromagnetic properties of matter. Time-dependent electromagnetic fields and Maxwell's equations. Electromagnetic waves, emission, absorption, and scattering of radiation. Relativistic electrodynamics and mechanics.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"3-442"}]},{"type":"Recitation","options":[{"days":["M","T"],"start":"13:00","end":"14:00","room":"34-302"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.07"},{"code":"8.13","title":"Experimental Physics I","level":"U","description":"First in a two-term advanced laboratory sequence in modern physics focusing on the professional and personal development of the student as a scientist through the medium of experimental physics. Experimental options cover special relativity, experimental foundations of quantum mechanics, atomic structure and optics, statistical mechanics, and nuclear and particle physics. Uses modern physics experiments to develop laboratory technique, systematic troubleshooting, professional scientific attitude, data analysis skills and reasoning about uncertainty. Provides extensive training in oral and written communication methods.","groups":[{"type":"Lab","options":[{"days":["M","W"],"start":"09:00","end":"12:00","room":"4-361"},{"days":["M","W"],"start":"14:00","end":"17:00","room":"4-361"},{"days":["T","R"],"start":"09:00","end":"12:00","room":"4-361"},{"days":["T","R"],"start":"14:00","end":"17:00","room":"4-361"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.13"},{"code":"8.231","title":"Physics of Solids I","level":"U","description":"Introduction to the basic concepts of the quantum theory of solids. Topics: periodic structure and symmetry of crystals; diffraction; reciprocal lattice; chemical bonding; lattice dynamics, phonons, thermal properties; free electron gas; model of metals; Bloch theorem and band structure, nearly free electron approximation; tight binding method; Fermi surface; semiconductors, electrons, holes, impurities; optical properties, excitons; and magnetism.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-261"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:00","end":"15:00","room":"2-135"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.231"},{"code":"8.284","title":"Modern Astrophysics","level":"U","description":"Application of physics (Newtonian, statistical, and quantum mechanics; special and general relativity) to fundamental processes that occur in celestial objects. Includes main-sequence stars, collapsed stars (white dwarfs, neutron stars, and black holes), pulsars, galaxies, active galaxies, quasars, and cosmology. Electromagnetic and gravitational radiation signatures of astrophysical phenomena explored through examination of observational data. No prior knowledge of astronomy required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:00","end":"15:30","room":"4-145"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.284"},{"code":"8.286","title":"The Early Universe","level":"U","description":"Introduction to modern cosmology. First half deals with the development of the big bang theory from 1915 to 1980, and latter half with recent impact of particle theory. Topics: special relativity and the Doppler effect, Newtonian cosmological models, introduction to non-Euclidean spaces, thermal radiation and early history of the universe, big bang nucleosynthesis, introduction to grand unified theories and other recent developments in particle theory, baryogenesis, the inflationary universe model, and the evolution of galactic structure.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"2-132"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.286"},{"code":"8.287","title":"Observational Techniques of Optical Astronomy","level":"U","description":"Fundamental physical and optical principles used for astronomical measurements at visible wavelengths and practical methods of astronomical observations. Topics: astronomical coordinates, time, optics, telescopes, photon counting, signal-to-noise ratios, data analysis (including least-squares model fitting), limitations imposed by the Earth's atmosphere on optical observations, CCD detectors, photometry, spectroscopy, astrometry, and time variability. Project at Wallace Astrophysical Observatory. Written and oral project reports. Limited to 18; preference to Course 8 and Course 12 majors and minors.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:00","end":"15:00","room":"55-110"}]},{"type":"Lab","options":[{"days":["M"],"start":"19:00","end":"21:00","room":"54-527"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.287"},{"code":"8.288","title":"Observational Stellar Archaeology","level":"U","description":"Covers the chemical evolution of the Milky Way, nucleosynthesis, and origins of the chemical elements in the early universe. Practical spectroscopic analysis, kinematic analysis, and students' own interpretation of chemical abundance patterns for a unique ancient star. Includes remote observations with the Magellan telescope in Chile.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"11:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.288"},{"code":"8.290","title":"Extrasolar Planets: Physics and Detection Techniques","level":"U","description":"Presents basic principles of planet atmospheres and interiors applied to the study of extrasolar planets. Focuses on fundamental physical processes related to observable extrasolar planet properties. Provides a quantitative overview of detection techniques. Introduction to the feasibility of the search for Earth-like planets, biosignatures and habitable conditions on extrasolar planets. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"54-209"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.290"},{"code":"8.321","title":"Quantum Theory I","level":"G","description":"A two-term subject on quantum theory, stressing principles: uncertainty relation, observables, eigenstates, eigenvalues, probabilities of the results of measurement, transformation theory, equations of motion, and constants of motion. Symmetry in quantum mechanics, representations of symmetry groups. Variational and perturbation approximations. Systems of identical particles and applications. Time-dependent perturbation theory. Scattering theory: phase shifts, Born approximation. The quantum theory of radiation. Second quantization and many-body theory. Relativistic quantum mechanics of one electron.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:30","end":"12:00","room":"56-114"}]},{"type":"Recitation","options":[{"days":["T"],"start":"15:00","end":"16:00","room":"26-322"},{"days":["R"],"start":"13:00","end":"14:00","room":"24-307"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.321"},{"code":"8.324","title":"Relativistic Quantum Field Theory II","level":"G","description":"The second term of the quantum field theory sequence. Develops in depth some of the topics discussed in 8.323 and introduces some advanced material. Topics: perturbation theory and Feynman diagrams, scattering theory, Quantum Electrodynamics, one loop renormalization, quantization of non-abelian gauge theories, the Standard Model of particle physics, other topics.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"16:30","end":"18:00","room":"56-154"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"26-328"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.324"},{"code":"8.333","title":"Statistical Mechanics I","level":"G","description":"First part of a two-subject sequence on statistical mechanics. Examines the laws of thermodynamics and the concepts of temperature, work, heat, and entropy. Postulates of classical statistical mechanics, microcanonical, canonical, and grand canonical distributions; applications to lattice vibrations, ideal gas, photon gas. Quantum statistical mechanics; Fermi and Bose systems. Interacting systems: cluster expansions, van der Waal's gas, and mean-field theory.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"32-155"}]},{"type":"Recitation","options":[{"days":["F"],"start":"14:30","end":"16:00","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.333"},{"code":"8.370","title":"Quantum Computation","level":"G","description":"Provides an introduction to the theory and practice of quantum computation. Topics covered: physics of information processing; quantum algorithms including the factoring algorithm and Grover's search algorithm; quantum error correction; quantum communication and cryptography. Knowledge of quantum mechanics helpful but not required.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"54-100"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.370"},{"code":"8.372","title":"Quantum Information Science III","level":"G","description":"Third subject in the Quantum Information Science (QIS) sequence, building on 8.370 and 8.371. Further explores core topics in quantum information science, such as quantum information theory, error-correction, physical implementations, algorithms, cryptography, and complexity. Draws connections between QIS and related fields, such as many-body physics, and applications such as sensing.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"2-136"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.372"},{"code":"8.398","title":"Doctoral Seminar in Physics","level":"G","description":"A seminar for first-year PhD students presenting topics of current interest, with content varying from year to year. Open only to first-year graduate students in Physics.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"12:00","end":"13:00","room":"26-414"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.398"},{"code":"8.422","title":"Atomic and Optical Physics II","level":"G","description":"The second of a two-term subject sequence that provides the foundations for contemporary research in selected areas of atomic and optical physics. Non-classical states of light- squeezed states; multi-photon processes, Raman scattering; coherence- level crossings, quantum beats, double resonance, superradiance; trapping and cooling- light forces, laser cooling, atom optics, spectroscopy of trapped atoms and ions; atomic interactions- classical collisions, quantum scattering theory, ultracold collisions; and experimental methods.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"32-124"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.422"},{"code":"8.511","title":"Theory of Solids I","level":"G","description":"First term of a theoretical treatment of the physics of solids. Concept of elementary excitations. Symmetry- translational, rotational, and time-reversal invariances- theory of representations. Energy bands- electrons and phonons. Topological band theory. Survey of electronic structure of metals, semimetals, semiconductors, and insulators, excitons, critical points, response functions, and interactions in the electron gas. Theory of superconductivity.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"2-105"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.511"},{"code":"8.513","title":"Many-Body Theory for Condensed Matter Systems","level":"G","description":"Concepts and physical pictures behind various phenomena that appear in interacting many-body systems. Visualization occurs through concentration on path integral, mean-field theories and semiclassical picture of fluctuations around mean-field state. Topics covered: interacting boson/fermion systems, Fermi liquid theory and bosonization, symmetry breaking and nonlinear sigma-model, quantum gauge theory, quantum Hall theory, mean-field theory of spin liquids and quantum order, string-net condensation and emergence of light and fermions.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"2-132"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.513"},{"code":"8.591","title":"Systems Biology","level":"G","description":"Introduction to cellular and population-level systems biology with an emphasis on synthetic biology, modeling of genetic networks, cell-cell interactions, and evolutionary dynamics.  Cellular systems include genetic switches and oscillators, network motifs, genetic network evolution, and cellular decision-making.  Population-level systems include models of pattern formation, cell-cell communication, and evolutionary systems biology. Students taking graduate version explore the subject in more depth.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"4-159"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.591"},{"code":"8.592","title":"Statistical Physics in Biology","level":"G","description":"A survey of problems at the interface of statistical physics and modern biology: bioinformatic methods for extracting information content of DNA; gene finding, sequence comparison, phylogenetic trees. Physical interactions responsible for structure of biopolymers; DNA double helix, secondary structure of RNA, elements of protein folding. Considerations of force, motion, and packaging; protein motors, membranes. Collective behavior of biological elements; cellular networks, neural networks, and evolution.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"26-314"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.592"},{"code":"8.613","title":"Introduction to Plasma Physics I","level":"G","description":"Introduces plasma phenomena relevant to energy generation by controlled thermonuclear fusion and to astrophysics. Elementary plasma concepts, plasma characterization. Motion of charged particles in magnetic fields. Coulomb collisions, relaxation times, transport processes. Two-fluid hydrodynamic and MHD descriptions. Plasma confinement by magnetic fields, simple equilibrium and stability analysis. Wave propagation in a magnetic field; application to RF plasma heating. Introduction to kinetic theory; Vlasov, Boltzmann and Fokker-Planck equations; relation of fluid and kinetic descriptions. Electron and ion acoustic plasma waves, Landau damping.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"NW14-1112"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.613"},{"code":"8.701","title":"Introduction to Nuclear and Particle Physics","level":"G","description":"The phenomenology and experimental foundations of particle and nuclear physics; the fundamental forces and particles, composites. Interactions of particles with matter, and detectors. SU(2), SU(3), models of mesons and baryons. QED, weak interactions, parity violation, lepton-nucleon scattering, and structure functions. QCD, gluon field and color. W and Z fields, electro-weak unification, the CKM matrix. Nucleon-nucleon interactions, properties of nuclei, single- and collective- particle models. Electron and hadron interactions with nuclei. Relativistic heavy ion collisions, and transition to quark-gluon plasma.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:30","end":"15:00","room":"8-205"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.701"},{"code":"8.811","title":"Particle Physics","level":"G","description":"Modern review of particles, interactions, and recent experiments. Experimental and analytical methods. QED, electroweak theory, and the Standard Model as tested in recent key experiments at ee and pp colliders. Mass generation, W, Z, and Higgs physics. Weak decays of mesons, including heavy flavors with QCD corrections. Mixing phenomena for K, D, B mesons and neutrinos. CP violation with results from B-factories. Future physics expectations: Higgs, SUSY, sub-structure as addressed by new experiments at the LHC collider.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"8-205"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.811"},{"code":"8.851","title":"Effective Field Theory","level":"G","description":"Covers the framework and tools of effective field theory, including: identifying degrees of freedom and symmetries; power counting expansions (dimensional and otherwise); field redefinitions, bottom-up and top-down effective theories; fine-tuned effective theories; matching and Wilson coefficients; reparameterization invariance; and advanced renormalization group techniques.  Main examples are taken from particle and nuclear physics, including the Soft-Collinear Effective Theory.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"2-151"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.851"},{"code":"8.902","title":"Astrophysics II","level":"G","description":"Galactic dynamics: potential theory, orbits, collisionless Boltzmann equation, etc. Galaxy interactions. Groups and clusters; dark matter. Intergalactic medium; x-ray clusters. Active galactic nuclei: unified models, black hole accretion, radio and optical jets, etc. Homogeneity and isotropy, redshift, galaxy distance ladder. Newtonian cosmology. Roberston-Walker models and cosmography. Early universe, primordial nucleosynthesis, recombination. Cosmic microwave background radiation. Large-scale structure, galaxy formation.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-261"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.902"},{"code":"8.942","title":"Cosmology","level":"G","description":"Thermal backgrounds in space. Cosmological principle and its consequences: Newtonian cosmology and types of 'universes'; survey of relativistic cosmology; horizons. Overview of evolution in cosmology; radiation and element synthesis; physical models of the 'early stages.' Formation of large-scale structure to variability of physical laws. First and last states. Some knowledge of relativity expected. 8.962 recommended though not required.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"2-151"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.942"},{"code":"8.998","title":"Teaching and Mentoring MIT Students","level":"U","description":"Designed for first-time physics mentors and others interested in improving their knowledge and skills in teaching one-on-one and in small groups, particularly TEAL TAs and graduate student TAs. Topics include: cognition, metacognition, and the role of affect; communication skills (practice listening, questioning, and eliciting student ideas); the roles of motivation and mindset in learning; fostering belonging and self-efficacy through peer mentorship; facilitating small-group interactions to enhance peer instruction and learning; physics-specific learning strategies, such as how to teach/learn problem solving; research-based techniques for effective mentorship in STEM. Includes a one-hour class on pedagogy topics, a one-hour weekly Physics Mentoring Community of Practice meeting, and weekly assignments to read or watch material in preparation for class discussions, and written reflections before class.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"11:00","end":"12:00","room":"1-246"},{"days":["T"],"start":"13:00","end":"14:00","room":"1-273"}]},{"type":"Lab","options":[{"days":["R"],"start":"13:00","end":"14:00","room":"1-273"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-273"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-375"}]}],"url":"http://student.mit.edu/catalog/m8b.html#8.998"},{"code":"8.EPE","title":"UPOP Engineering Practice Experience","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.EPE"},{"code":"8.THT","title":"Thesis Tutorial","level":"U","description":"Supervised guidance of a research paper from draft to pre-publication. Through in-class presentations and discussion, peer input/review, and revision, students create a 1000-word summary for scientists, and a full research paper on an existing UROP. Papers with completed projects may be uploaded to arXiv. Instruction and practice in oral and written communication provided. Students taking 8.THT must also enroll in 8.THU to receive CI-M credit. Limited to 10.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"10:00","end":"13:00","room":"2-142"}]}],"url":"http://student.mit.edu/catalog/m8a.html#8.THT"},{"code":"9.01","title":"Introduction to Neuroscience","level":"U","description":"Introduction to the mammalian nervous system, with emphasis on the structure and function of the human brain. Topics include the function of nerve cells, sensory systems, control of movement, learning and memory, and diseases of the brain.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"46-3002"}]},{"type":"Recitation","options":[{"days":["R"],"start":"12:00","end":"13:00","room":"46-1015"},{"days":["R"],"start":"19:00","end":"20:00","room":"46-3037"},{"days":["F"],"start":"11:00","end":"12:00","room":"46-3037"},{"days":["F"],"start":"13:00","end":"14:00","room":"46-3037"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.01"},{"code":"9.011","title":"Systems Neuroscience Core I","level":"G","description":"Survey of brain and behavioral studies. Examines principles underlying the structure and function of the nervous system, with a focus on systems approaches. Topics include development of the nervous system and its connections, sensory systems of the brain, the motor system, higher cortical functions, and behavioral and cellular analyses of learning and memory. Preference to first-year graduate students in BCS.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"14:00","end":"16:00","room":"46-5313"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.011"},{"code":"9.014","title":"Quantitative Methods and Computational Models in Neurosciences","level":"G","description":"Provides theoretical background and practical skills needed to analyze and model neurobiological observations at the molecular, systems and cognitive levels. Develops an intuitive understanding of mathematical tools and computational techniques which students apply to analyze, visualize and model research data using MATLAB programming. Topics include linear systems and operations, dimensionality reduction (e.g., PCA), Bayesian approaches, descriptive and generative models, classification and clustering, and dynamical systems. Limited to 18; priority to current BCS Graduate students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"10:00","end":"12:00","room":"46-1015"}]},{"type":"Lab","options":[{"days":["F"],"start":"10:00","end":"12:00","room":"46-1015"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.014"},{"code":"9.015","title":"Molecular and Cellular Neuroscience Core I","level":"G","description":"Survey and primary literature review of selected major topic areas in molecular and cellular neurobiology. Covers nervous system development, axonal pathfinding, synapse formation and function, synaptic plasticity, ion channels and receptors, cellular neurophysiology, glial cells, sensory transduction, and relevant examples in human disease. Includes lectures and weekly paper write-ups, together with student presentations and discussion of primary literature. A final two-page research write-up is also due at the end of the term.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"46-4062"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.015"},{"code":"9.15","title":"Neural Circuits, Neuromodulatory, and Neuroendocrine Systems","level":"U","description":"Studies how neural circuits give rise to behavior, and how neuromodulatory systems and pharmacological intervention can influence these processes. Lectures and selected publications cover the fundamentals of neuropharmacology, neuromodulatory systems, and approaches to understand circuit mechanisms. Provides a historical view of various neurotransmitter or neuromodulatory systems as well as an understanding of how research is conducted at the forefront of neuroscience today. Instruction and practice in oral and written communication provided. Students present a primary research article and also submit a research proposal which they have the opportunity to revise based on feedback.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"46-3015"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.15"},{"code":"9.16","title":"Cellular and Synaptic Neurophysiology","level":"U","description":"Surveys the mechanisms of neuronal communication. Covers ion channels in excitable membrane, single cell computation, synaptic transmission, and synaptic plasticity. Correlates the properties of ion channels and synaptic transmission with their physiological function. Discusses the organizational principles for the formation of functional neural networks at synaptic and cellular levels. Involves discussion of primary literature.  Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"46-4062"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.16"},{"code":"9.160","title":"Cellular and Synaptic Neurophysiology","level":"G","description":"Surveys the mechanisms of neuronal communication. Covers ion channels in excitable membrane, single cell computation, synaptic transmission, and synaptic plasticity. Correlates the properties of ion channels and synaptic transmission with their physiological function. Discusses the organizational principles for the formation of functional neural networks at synaptic and cellular levels. Involves discussion of primary literature.  Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"46-4062"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.160"},{"code":"9.17","title":"Systems Neuroscience Laboratory","level":"U","description":"Consists of a series of laboratories designed to give students experience with basic techniques for conducting systems neuroscience research. Includes sessions on anatomical, neurophysiological, and data acquisition and analysis techniques, and how these techniques are used to study nervous system function. Involves the use of experimental animals. Assignments include weekly preparation for lab sessions, two major lab reports and a series of basic computer programming tutorials (MATLAB). Instruction and practice in written communication provided.  Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"16:00","room":"46-3310"}]},{"type":"Lab","options":[{"days":["F"],"start":"13:00","end":"17:00","room":"46-1024"}]},{"type":"Recitation","options":[{"days":["T"],"start":"10:00","end":"11:00","room":"46-3310"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.17"},{"code":"9.175","title":"Robotics","level":"G","description":"Introduction to robotics and learning in machines. Kinematics and dynamics of rigid body systems. Adaptive control, system identification, sparse representations. Force control, adaptive visual servoing. Task planning, teleoperation, imitation learning. Navigation. Underactuated systems, approximate optimization and control. Dynamics of learning and optimization in networks. Elements of biological planning and control. Motor primitives, entrainment, active sensing, binding models. Term projects.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"5-217"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.175"},{"code":"9.36","title":"Neurobiology of Self","level":"U","description":"Discusses the neurobiological mechanisms that distinguish 'the Self' from external environment; the neural circuits that enable us to know that 'the Self' is in pain, or feels hungry, thirsty, and tired; and the neurons and circuits that lead to the emotional and moody Self. Examines brain mechanism that encodes the body schema and the Self in space. This includes the neural computations that allow, for example, the hand to know where the mouth is. Discusses the possibility of making robots develop a sense of Self, as well as disorders and delusions of the Self. Contemporary research — ranging from molecules, cells, circuits, to systems in both animal models and humans — explored. Students in the graduate version do additional classwork or projects.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"46-3189"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.36"},{"code":"9.360","title":"Neurobiology of Self","level":"G","description":"Discusses the neurobiological mechanisms that distinguish 'the Self' from external environment; the neural circuits that enable us to know that 'the Self' is in pain, or feels hungry, thirsty, and tired; and the neurons and circuits that lead to the emotional and moody Self. Examines brain mechanism that encodes the body schema and the Self in space. This includes the neural computations that allow, for example, the hand to know where the mouth is. Discusses the possibility of making robots develop a sense of Self, as well as disorders and delusions of the Self. Contemporary research — ranging from molecules, cells, circuits, to systems in both animal models and humans — explored. Students in the graduate version do additional classwork or projects.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"46-3189"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.360"},{"code":"9.41","title":"Research and Communication in Neuroscience and Cognitive Science","level":"U","description":"Emphasizes research and scientific communication. Instruction and practice in written and oral communication provided. Based on results of his/her UROP research, each student creates a full-length paper and a poster as part of an oral presentation at the end of the term. Other assignments include peer editing and reading/critiquing published research papers. Prior to starting class, students must have collected enough data from their UROP research projects to write a paper. Limited to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"12:30","end":"14:30","room":"46-5056"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.41"},{"code":"9.422","title":"Principles of Neuroengineering","level":"G","description":"Covers how to innovate technologies for brain analysis and engineering, for accelerating the basic understanding of the brain, and leading to new therapeutic insight and inventions. Focuses on using physical, chemical and biological principles to understand technology design criteria governing ability to observe and alter brain structure and function. Topics include optogenetics, noninvasive brain imaging and stimulation, nanotechnologies, stem cells and tissue engineering, and advanced molecular and structural imaging technologies. Includes design projects. Designed for students with engineering maturity who are ready for design. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"46-5165"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.422"},{"code":"9.455","title":"Revolutionary Ventures: How to Invent and Deploy Transformative Technologies","level":"G","description":"Seminar on envisioning and building ideas and organizations to accelerate engineering revolutions. Focuses on emerging technology domains, such as neurotechnology, imaging, cryotechnology, gerontechnology, and bio-and-nano fabrication. Draws on historical examples as well as live case studies of existing or emerging organizations, including labs, institutes, startups, and companies. Goals range from accelerating basic science to developing transformative products or therapeutics. Each class is devoted to a specific area, often with invited speakers, exploring issues from the deeply technical through the strategic. Individually or in small groups, students prototype new ventures aimed at inventing and deploying revolutionary technologies.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"16:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.455"},{"code":"9.49","title":"Neural Circuits for Cognition","level":"U","description":"Takes a computational approach to examine circuits in the brain that perform elemental cognitive tasks: tasks that are neither directly sensory nor directly motor in function, but are essential to bridging from perception to action. Covers circuits and circuit motifs in the brain that underlie computations like integration, decision-making, spatial navigation, inference, and other cognitive elements. Students study empirical results, build dynamical models of neural circuits, and examine the mathematical theory of representations and computation in such circuits. Considers noise, stability, plasticity, and learning rules for these systems. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"46-3310"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.49"},{"code":"9.490","title":"Neural Circuits for Cognition","level":"G","description":"Takes a computational approach to examine circuits in the brain that perform elemental cognitive tasks: tasks that are neither directly sensory nor directly motor in function, but are essential to bridging from perception to action. Covers circuits and circuit motifs in the brain that underlie computations like integration, decision-making, spatial navigation, inference, and other cognitive elements. Students study empirical results, build dynamical models of neural circuits, and examine the mathematical theory of representations and computation in such circuits. Considers noise, stability, plasticity, and learning rules for these systems. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"46-3310"}]}],"url":"http://student.mit.edu/catalog/m9a.html#9.490"},{"code":"9.520","title":"Statistical Learning Theory and Applications","level":"G","description":"Covers foundations and recent advances in statistical machine learning theory, with the dual goals of providing students with the theoretical knowledge to use machine learning and preparing more advanced students to contribute to progress in the field. The content is roughly divided into three parts. The first part is about classical regularization, margin, stochastic gradient methods, overparametrization, implicit regularization, and stability. The second part is about deep networks: approximation and optimization theory plus roots of generalization. The third part is about the connections between learning theory and the brain. Occasional talks by leading researchers on advanced research topics. Emphasis on current research topics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"46-3002"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.520"},{"code":"9.522","title":"Statistical Reinforcement Learning","level":"G","description":"Focuses on sample complexity and algorithms for online learning and decision-making. Prediction of individual sequences, online regression, and online density estimation. Multi-armed and contextual bandits. Decision-making with structured observations and the decision-estimation coefficient. Frequentist and Bayesian approaches. Reinforcement learning: tabular methods and function approximation. Behavioral and neural mechanisms of reinforcement learning.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"46-3002"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.522"},{"code":"9.583","title":"Functional Magnetic Resonance Imaging: Data Acquisition and Analysis","level":"G","description":"Provides background necessary for designing, conducting, and interpreting fMRI studies in the human brain. Covers in depth the physics of image encoding, mechanisms of anatomical and functional contrasts, the physiological basis of fMRI signals, cerebral hemodynamics, and neurovascular coupling. Also covers design methods for stimulus-, task-driven and resting-state experiments, as well as workflows for model-based and data-driven analysis methods for data. Instruction in brain structure analysis and surface- and region-based analyses. Laboratory sessions include data acquisition sessions at the 3 Tesla MRI scanner at MIT and the Connectom and 7 Tesla scanners at the MGH/HST Martinos Center, as well as hands-on data analysis workshops. Introductory or college-level neurobiology, physics, and signal processing are helpful.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:00","room":"4-231"}]},{"type":"Lab","options":[{"days":["M"],"start":"12:30","end":"14:00","room":"4-149"}]},{"type":"Recitation","options":[{"days":["W"],"start":"14:00","end":"15:00","room":"4-231"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.583"},{"code":"9.66","title":"Computational Cognitive Science","level":"U","description":"Introduction to computational theories of human cognition. Focus on principles of inductive learning and inference, and the representation of knowledge. Computational frameworks covered include Bayesian and hierarchical Bayesian models; probabilistic graphical models; nonparametric statistical models and the Bayesian Occam's razor; sampling algorithms for approximate learning and inference; and probabilistic models defined over structured representations such as first-order logic, grammars, or relational schemas. Applications to understanding core aspects of cognition, such as concept learning and categorization, causal reasoning, theory formation, language acquisition, and social inference. Graduate students complete a final project.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"46-3002"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.66"},{"code":"9.660","title":"Computational Cognitive Science","level":"G","description":"Introduction to computational theories of human cognition. Focuses on principles of inductive learning and inference, and the representation of knowledge. Computational frameworks include Bayesian and hierarchical Bayesian models, probabilistic graphical models, nonparametric statistical models and the Bayesian Occam's razor, sampling algorithms for approximate learning and inference, and probabilistic models defined over structured representations such as first-order logic, grammars, or relational schemas. Applications to understanding core aspects of cognition, such as concept learning and categorization, causal reasoning, theory formation, language acquisition, and social inference. Graduate students complete a final project.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"46-3002"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.660"},{"code":"9.72","title":"Vision in Art and Neuroscience","level":"U","description":"Introduces and provides practical engagement with core concepts in vision neuroscience. Combination of seminar and studio work fosters interdisciplinary dialogue between visual art and vision neuroscience, culminating in a gallery exhibition of students' individual, semester-long projects. Treats the processes of visual perception and the creation of visual art in parallel, making use of the fact that both are constructive. Through lectures and readings in experimental and computational vision research, explores the hierarchy of visual processing, from the moment that light strikes the retina to the internal experience of a rich visual world. In the studio, students examine how each stage of this process manifests in the experience of art, wherein the perceptual system observes itself. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"10-150"}]},{"type":"Lab","options":[{"days":["R"],"start":"15:00","end":"17:00","room":"10-150"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.72"},{"code":"9.720","title":"Vision in Art and Neuroscience","level":"G","description":"Introduces and provides practical engagement with core concepts in vision neuroscience. Combination of seminar and studio work fosters interdisciplinary dialogue between visual art and vision neuroscience, culminating in a gallery exhibition of students' individual, semester-long projects. Treats the processes of visual perception and the creation of visual art in parallel, making use of the fact that both are constructive. Through lectures and readings in experimental and computational vision research, explores the hierarchy of visual processing, from the moment that light strikes the retina to the internal experience of a rich visual world. In the studio, students examine how each stage of this process manifests in the experience of art, wherein the perceptual system observes itself. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"10-150"}]},{"type":"Lab","options":[{"days":["R"],"start":"15:00","end":"17:00","room":"10-150"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.720"},{"code":"9.85","title":"Infant and Early Childhood Cognition","level":"U","description":"Introduction to cognitive development focusing on childrens' understanding of objects, agents, and causality. Develops a critical understanding of experimental design. Discusses how developmental research might address philosophical questions about the origins of knowledge, appearance and reality, and the problem of other minds.  Provides instruction and practice in written communication as necessary to research in cognitive science (including critical reviews of journal papers, a literature review and an original research proposal), as well as instruction and practice in oral communication in the form of a poster presentation of a journal paper.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"46-3189"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.85"},{"code":"9.918","title":"BCS Grant Writing Workshop","level":"G","description":"Fellowship writing workshop to develop applications for predoctoral fellowships, including the NSF and NDSEG programs.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"17:00","end":"19:00","room":"46-3189"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.918"},{"code":"9.C20","title":"Introduction to Computational Science and Engineering","level":"U","description":"Provides an introduction to computational algorithms used throughout engineering and science (natural and social) to simulate time-dependent phenomena; optimize and control systems; and quantify uncertainty in problems involving randomness, including an introduction to probability and statistics. Combination of 6.100A and 16.C20J counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/m9b.html#9.C20"},{"code":"CC.010","title":"Seminar I","level":"U","description":"The key academic integration in which philosophical, historical, and sociological topics are connected with modern science. Combination of outside speakers and Concourse faculty lead weekly luncheon discussion. Subject can count toward the 6-unit discovery-focused credit limit for first year students. Limited to Concourse students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"11:00","end":"13:00","room":"16-128"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.010"},{"code":"CC.012","title":"Continuing Conversations","level":"U","description":"Close reading and vigorous discussion of an important book or theme, chosen to explore philosophical, ethical, and political questions that span the ages and disciplines.  Readings and themes vary by term.  Past examples include Aristotle's Physics, Plato's dialogue on knowledge, the Theaetetus, and a variety of writings that exemplify liberalism and conservatism in the American tradition. Preference to Concourse students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"15:00","end":"17:00","room":"16-128"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.012"},{"code":"CC.110","title":"Becoming Human: Ancient Greek Perspectives on the Good Life","level":"U","description":"Explores the question of the good life in the major literary and philosophic thinkers of ancient Greece.  Considers topics such as justice, moral virtue, friendship, love, and the life of the mind both for an individual and as part of society. Students debate the classical Greek answers to these questions and consider ways in which these answers apply to our present lives.  Includes selected works by authors such as Homer, Sophocles, Euripides, Aristophanes, Plato, Aristotle, and Epicurus. Limited to students in Concourse.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:30","end":"11:00","room":"16-160"},{"days":["T"],"start":"15:00","end":"16:30","room":"16-160"}]},{"type":"Recitation","options":[{"days":["W"],"start":"12:00","end":"13:00","room":"16-136"},{"days":["W"],"start":"16:00","end":"17:00","room":"16-136"},{"days":["R"],"start":"13:00","end":"14:00","room":"16-136"},{"days":["R"],"start":"16:00","end":"17:00","room":"16-136"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.110"},{"code":"CC.115","title":"Writing About Big Questions: Defending Poetry","level":"U","description":"Intensive focus on the reading and writing skills used to analyze a variety of challenging texts. Coverage includes Platonic dialogues and other works of philosophy, poetic treatises (like Sidney's Defense of Poesy, or Wordsworth and Coleridge's 'Preface' to Lyrical Ballads), and creative works by the same writers, as well as criticism that probes how such texts may relate to, qualify, and inform each other. Students practice various forms of argument, orally and in writing, and consider how purpose and audience may influence one's approach. Designed to prepare students for further work in the liberal arts, as well as to promote increased confidence and enjoyment in reading, writing, and analysis. Students write or revise essays throughout the term. Preference given to Concourse students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"4-251"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.115"},{"code":"CC.120","title":"Making Books in the Renaissance and Today","level":"U","description":"Explores the impact of new technology on the recording and distribution of words and images in Europe from 1400-1800. Assignments include essays and online projects. Students participate in the design and printing of an eight-page pamphlet on a hand-set printing press. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.120"},{"code":"CC.1802","title":"Calculus","level":"U","description":"Equivalent to 18.02; see 18.02 for description. Limited to students in Concourse.","groups":[{"type":"Lecture","options":[{"days":["T","R","F"],"start":"13:00","end":"14:00","room":"16-160"}]},{"type":"Recitation","options":[{"days":["M","W"],"start":"12:00","end":"13:00","room":"16-160"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.1802"},{"code":"CC.181A","title":"Calculus","level":"U","description":"Equivalent to 18.01A; see 18.01A for description. Limited to students in Concourse.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"16-160"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"16-160"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.181A"},{"code":"CC.182A","title":"Calculus","level":"U","description":"Equivalent to 18.02A; see 18.02A for description. Limited to students in Concourse.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:30","room":"16-160"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"13:00","end":"14:00","room":"16-160"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.182A"},{"code":"CC.5111","title":"Principles of Chemical Science","level":"U","description":"Equivalent to 5.111; see 5.111 for description. Limited to students in Concourse.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"16-160"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"11:00","end":"12:00","room":"16-160"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.5111"},{"code":"CC.801","title":"Physics I","level":"U","description":"Equivalent to 8.01; see 8.01 for description. Limited to students in Concourse.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"16-160"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"14:00","end":"15:00","room":"16-160"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.801"},{"code":"CC.8012","title":"Physics I","level":"U","description":"Equivalent to 8.012; see 8.012 for description. Limited to students in Concourse.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"16-160"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"16-160"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.8012"},{"code":"CC.S20","title":"Special Subject: Concourse","level":"U","description":"Covers topics not included in the permanent curriculum. May be repeated for credit with permission of instructor. Preference to students in Concourse.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"12:00","end":"13:30","room":"16-136"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.S21"},{"code":"CC.S21","title":"Special Subject: Concourse","level":"U","description":"Covers topics not included in the permanent curriculum. May be repeated for credit with permission of instructor. Preference to students in Concourse.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"12:00","end":"13:00","room":"16-136"}]}],"url":"http://student.mit.edu/catalog/mCCa.html#CC.S21"},{"code":"CMS.100","title":"Introduction to Media Studies","level":"U","description":"Offers an overview of the social, cultural, political, and economic impact of mediated communication on modern culture. Combines critical discussions with experiments working with different media. Media covered include radio, television, film, the printed word, and digital technologies. Topics include the nature and function of media, core media institutions, and media in transition. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"16:00","room":"1-371"},{"days":["W","F"],"start":"13:00","end":"14:30","room":"35-308"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.100"},{"code":"CMS.300","title":"Game Studies","level":"U","description":"Introduction to the interdisciplinary study of videogames as texts through an examination of their cultural, educational, and social functions in contemporary settings. Students play and analyze videogames while reading current research and theory from a variety of sources in the sciences, social sciences, humanities, and industry. Assignments focus on game analysis in the context of the theories discussed in class. Includes regular reading, writing, and presentation exercises. No prior programming experience required. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.300"},{"code":"CMS.303","title":"DJ History, Technique, and Technology","level":"U","description":"Students explore a chosen contemporary or historical dance scene from around the world. Lectures examine the evolution of the craft and technologies of the DJ. Presents foundational practices of live DJ mixing; practice equipment is accessible to teams of students. Assignments include writing a report analyzing a book on DJ history or technique, producing a complete mix, and participation in an end-of-term performance. No prior experience is necessary, but students must sustain interest in some form of popular dance music, broadly defined. Graduate students complete additional assignments. Limited to 24.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.303"},{"code":"CMS.306","title":"Making Comics and Sequential Art","level":"U","description":"Applied introduction to comics and sequential art production. Builds skills in how to develop storylines; develop and draw characters, panels, and backgrounds; prepare for print production; and comprehend the basics of sequential language, composition, and layout. Students engage with crucial personal and political issues at stake across a range of comics genres: superhero, biographical, and countercultural. Addresses not just how we create comics, but why we create comics. Students taking graduate version complete additional assignments. Limited to 16.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.306"},{"code":"CMS.307","title":"Critical Worldbuilding","level":"U","description":"Studies the design and analysis of invented (or constructed) worlds for narrative media, such as television, films, comics, and literary texts. Provides the practical, historical and critical tools with which to understand the function and structure of imagined worlds. Examines world-building strategies in the various media and genres in order to develop a critical and creative repertoire. Participants create their own invented worlds. Students taking graduate version complete additional assignments. Limited to 13.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"4-257"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.307"},{"code":"CMS.330","title":"Studies in Film","level":"U","description":"Intensive study of films from particular periods, genres, or directors, or films focusing on specific formal or theoretical problems. Instruction and practice in oral and written communication provided. Previous topics include The Contemporary Horror Film, Film Remixes, Film Narrative, Heroic Cinema, Color in Film and Hitchcock. Students taking graduate version complete different assignments. May be repeated for credit with permission of instructor if content differs. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"2-143"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.330"},{"code":"CMS.336","title":"Social Justice and The Documentary Film","level":"U","description":"Explores the history and current state of social-issue documentary. Examines how cultural and political upheaval and technological change have converged at different moments to bring about new waves of activist documentary film production. Particular focus on films and other non-fiction media of the present and recent past. Students screen and analyze a series of key films and work in groups to produce their own short documentary using digital video and computer-based editing. Students taking graduate version complete additional assignments. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.336"},{"code":"CMS.342","title":"Designing Virtual Worlds","level":"U","description":"Three primary areas of focus are: creating new Virtual Reality experiences; mapping the state of emerging tools; and hosting guests ? leaders in the VR/XR community, who serve as coaches for projects. Students have significant leeway to customize their own learning environment. As the field is rapidly evolving, each semester focuses on a new aspect of virtual worlds, based on the current state of innovations. Students work in teams of interdisciplinary peers from Berklee College of Music and Harvard University. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:30","end":"16:30","room":"3-370"}]},{"type":"Recitation","options":[{"days":["T"],"start":"19:00","end":"20:00","room":"9-152"},{"days":["W"],"start":"19:00","end":"20:00","room":"9-152"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.342"},{"code":"CMS.357","title":"Creation of a Continent: Media Representations of Hispanic America, 1492 to present","level":"U","description":"Traces the creation of a new literature in Spanish to record and interpret New World experiences. Begins with excerpts from Columbus's diary and ends with writings on the late 19th-century Cuban and Puerto Rican independence movements. Pairs some of these pre-20th-century texts with more recent literary and film interpretations of the first 400 years of Hispanic American history. Conducted in Spanish.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"56-167"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.357"},{"code":"CMS.359","title":"Three Kingdoms: From History to Fiction, Comic, Film, and Game","level":"U","description":"Analyzing core chapters of the great Chinese epic novel, Three Kingdoms, and its adaptations across diverse media, considers what underlies the appeal of this classic narrative over the centuries. Through focus on historical events in the period 206 BC to AD 280, examines the representation of power, diplomacy, war, and strategy, and explores the tension among competing models of political authority and legitimacy. Covers basic elements of classical Chinese political and philosophical thought, and literary and cultural history. Final group project involves digital humanities tools. Readings in translation. Films and video in Chinese with English subtitles.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.359"},{"code":"CMS.375","title":"Reading Climate Through Media","level":"U","description":"Explores how climate is construed in the contemporary media in order to gain a better understanding of how views of climate change are shaped and received in the public sphere. Studies the pathways that take us from climate science to media content, from the big data of global scale to the particulars and narratives of the human experience. Surveys a variety of media forms--reports, articles, comics, videos, films, photography, poetry and fiction--that reflect on the contemporary human challenges of dealing with a changing natural environment of our own making. Emphasizes the role of media in shaping public opinion, both in the US and globally, and its influence on public (and voter) perceptions on which a vast body of regulation and funding for environmental management is based. Students work individually and in teams to produce a selection of the media forms studied. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.375"},{"code":"CMS.376","title":"History of Media and Technology","level":"U","description":"Surveys the interrelated histories of communications media and technological development, from the emergence of 19th-century forms of mass print media and telegraphy, to sound capture and image-based forms (e.g., film, radio, and television), to the shift from analog to digital cultures. Examines how new forms of communication exert social, political, and cultural influences in the global context. Explores how technological innovation and accelerating media affect social values and behaviors in the popular and global adoption of a media device. Includes two papers and a research project on aspects of media history. Students taking graduate version complete additional assignments. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.376"},{"code":"CMS.379","title":"The Modern Newsroom: Principles and Practices","level":"U","description":"Offers an introduction to news writing and production. Presents the basics of journalism, including its core ethical tenets, news writing and reporting techniques, media literacy, deadline-driven production processes, and newsroom standards. Students complete a broad range of journalistic pieces, including assignments on news and scientific reporting, local and field reporting, opinion writing, editing, and fact-checking, some of which may be published in The Tech. Students are expected to come to class prepared to discuss major news events as well as weekly readings from major journalism outlets. Learning objectives are to gain a clear idea of what makes a strong news story successful, hone reporting and analytic skills, create a portfolio of journalistic work, and exercise a strong grasp of ethical practices and procedures that guide newsrooms across the world.  Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.379"},{"code":"CMS.401","title":"The Algorithmic Eye: Computing and Visual Media","level":"U","description":"Studies how the use of computers to produce, capture, and comprehend views of the world has transformed visual culture. Tracks the development of computational imaging across media history (from art, photography, and film to video games and computer vision). Students uncover the cultural stakes of computational imaging when it comes to questions of aesthetics, surveillance, automation, and infrastructure. Instruction and practice in oral and written communication provided. Students taking graduate version complete additional assignments.  Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.401"},{"code":"CMS.405","title":"Visual Design","level":"U","description":"Examines the process of making and sharing visual artifacts using a trans-cultural, trans-historical, constructionist approach. Explores the relationship between perceived reality and the narrative imagination, how an author's choice of medium and method constrains the work, how desire is integrated into the structure of a work, and how the cultural/economic opportunity for exhibition/distribution affects the realization of a work. Instruction and practice in written and oral communication provided. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.405"},{"code":"CMS.406","title":"The Anthropology of Sound","level":"U","description":"Examines the ways humans experience sound and how perceptions and technologies of sound emerge from cultural, economic, and historical worlds. Consider how the sound/noise/music boundaries have been imagined, created, and modeled across sociocultural and historical contexts. Learn how environmental, linguistic, and musical sounds are construed cross-culturally as well as the rise of telephony, architectural acoustics, sound recording, multi-channel and spatial mix performance, and the globalized travel of these technologies. Questions of sound ownership, property, authorship, remix, and copyright in the digital age are also addressed.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.406"},{"code":"CMS.422","title":"Representing Girlhood","level":"U","description":"Invites students to analyze cultural artifacts that represent girlhood from various eras and genres, including novels, children's literature, poetry, film, television, and popular music. Conceives girlhood in a broadly inclusive way, putting a range of materials — e.g., cultural artifacts that center Black, Jewish, Asian, and queer girls — in conversation with one another, by artists like Toni Morrison, Judy Blume, Andrea Wang, and Chappell Roan. Helps students build their oral presentation skills. Includes field trips to local museums or cultural events. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14N-325"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.422"},{"code":"CMS.425","title":"Children and Culture","level":"U","description":"Explores the relationship between children and the culture they inhabit in a particular time and place. Invites students to analyze in detail the image of childhood that emerges from many different media, including novels, children's literature, drama, film, television, dance, and popular song. Encourages students to take an interdisciplinary 'childhood studies' approach to youth culture that incorporates insights from literary and media studies, women's and gender studies, and the history and philosophy of childhood. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"56-180"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.425"},{"code":"CMS.435","title":"Literature and Film","level":"U","description":"Investigates relationships between the two media, including film adaptations as well as works linked by genre, topic, and style. Explores how artworks challenge and cross cultural, political, and aesthetic boundaries. Students taking graduate version complete additional assignments. May be repeated for credit with permission of instructor if content differs.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"22:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.435"},{"code":"CMS.586","title":"Introduction to Education: Looking Forward and Looking Back on Education","level":"U","description":"One of two introductory subjects on teaching and learning science and mathematics in a variety of K-12 settings. Topics include education and media, education reform, the history of education, simulations, games, and the digital divide. Students gain practical experience through weekly visits to schools, classroom discussions, selected readings, and activities to develop a critical and broad understanding of past and current forces that shape the goals and processes of education, and explores the challenges and opportunities of teaching. Students work collaboratively and individually on papers, projects, and in-class presentations. Limited to 25.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.586"},{"code":"CMS.591","title":"Educational Theory and Practice I","level":"U","description":"Concentrates on core set of skills and knowledge necessary for teaching in secondary schools. Topics include classroom management, student behavior and motivation, curriculum design, educational reform, and the teaching profession. Classroom observation is a key component. Assignments include readings from educational literature, written reflections on classroom observations, practice teaching and constructing curriculum. The first of the three-course sequence necessary to complete the Teacher Education Program. Limited to 15; preference to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"16:00","end":"17:30","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.591"},{"code":"CMS.594","title":"Education Technology Studio","level":"U","description":"Uses media and technology to develop new forms of learning experiences for schools, workplace, and informal settings. Students participate in a range of projects that hone understanding and skills in learning science, instructional design, development, and evaluation. Topics vary but include developing new media and activities for massive open online courses, creating practice spaces for practitioners in the professions and humanities, and developing new approaches to assessment in complex learning environments. May be repeated for credit with permission of instructor if project content differs. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.594"},{"code":"CMS.595","title":"Learning, Media, and Technology","level":"U","description":"Addresses new digital technologies that are transforming learning across the lifespan - from reading apps for toddlers, intelligent tutors for school children, and blended learning for college students, to MOOCs for adults and interest-based learning communities for hobbyists. Focuses on how these technologies shape people's lives and learning. Students explore how education technologies operate in complex social-technical systems, and acquire analytic tools and strategies that can be applied to other complex systems. They also refine their thinking about the opportunities, limits, and tradeoffs of educational technology. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"56-191"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.595"},{"code":"CMS.611","title":"Creating Video Games","level":"U","description":"Introduces students to the complexities of working in small, multidisciplinary teams to develop video games. Covers creative design and production methods, stressing design iteration and regular testing across all aspects of game development (design, visual arts, music, fiction, and programming). Assumes a familiarity with current video games, and the ability to discuss games critically. Previous experience in audio design, visual arts, or project management recommended. Limited to 36.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"16:00","room":"32-124"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.611"},{"code":"CMS.614","title":"Critical Internet Studies","level":"U","description":"Focuses on the power dynamics in internet-related technologies (including social networking platforms, surveillance technology, entertainment technologies, and emerging media forms). Theories and readings focus on the cultural, social, economic, and political aspects of internet use and design, with a special attention to gender and race. Topics include: online communication and communities, algorithms and search engines, activism and online resistance, surveillance and privacy, content moderation and platform governance, and the spread of dis- and misinformation. Instruction and practice in written and oral communication provided. Students taking the graduate version complete additional readings and assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.614"},{"code":"CMS.619","title":"Gender and Media Studies","level":"U","description":"Examines representations of race, gender, and sexual identity in the media. Considers issues of authorship, spectatorship, and the ways in which various media (film, television, print journalism, advertising) enable, facilitate, and challenge these social constructions in society. Studies the impact of new media and digital media through analysis of gendered and racialized language and embodiment online in blogs and vlogs, avatars, and in the construction of cyberidentities. Provides introduction to feminist approaches to media studies by drawing from work in feminist film theory, cultural studies, gender and politics, and cyberfeminism.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"19:00","end":"20:30","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.619"},{"code":"CMS.627","title":"Imagination, Computation, and Expression Studio","level":"U","description":"Aims to help students invent and analyze new forms of computer-based art, gaming, social media, interactive narrative, and related technologies. Students participate in a range of new and ongoing projects that are designed to hone skills in research, development, design, and evaluation. Topics vary from year to year; examples include cognitive science and artificial intelligence-based approaches to the arts; social aspects of game design; computing for social empowerment; and game character, avatar, and online profile design. May be repeated for credit with permission of instructor. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.627"},{"code":"CMS.701","title":"Current Debates in Media","level":"U","description":"Addresses important, current debates in media with in-depth discussion of popular perceptions and policy implications. Students use multiple perspectives to analyze texts emanating from these debates, and present their findings through discussions and reports. Explores emerging topics (e.g., piracy and IP regimes, net neutrality, media effects, social media and social change, and changing literacies) across media forms and from various historical, transcultural, and methodological perspectives. Examines the framing of these issues, their ethical and policy implications, and strategies for repositioning the debate. Instruction and practice in written and oral communication provided. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"5-231"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.701"},{"code":"CMS.803","title":"DJ History, Technique, and Technology","level":"G","description":"Students explore a chosen contemporary or historical dance scene from around the world. Lectures examine the evolution of the craft and technologies of the DJ. Presents foundational practices of live DJ mixing; practice equipment is accessible to teams of students. Assignments include writing a report analyzing a book on DJ history or technique, producing a complete mix, and participation in an end-of-term performance. No prior experience is necessary, but students must sustain interest in some form of popular dance music, broadly defined. Graduate students complete additional assignments. Limited to 24.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.803"},{"code":"CMS.806","title":"Making Comics and Sequential Art","level":"G","description":"Applied introduction to comics and sequential art production. Builds skills in how to develop storylines; develop and draw characters, panels, and backgrounds; prepare for print production; and comprehend the basics of sequential language, composition, and layout. Students engage with crucial personal and political issues at stake across a range of comics genres: superhero, biographical, and countercultural. Addresses not just how we create comics, but why we create comics. Students taking graduate version complete additional assignments. Limited to 16.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"1-150"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.806"},{"code":"CMS.807","title":"Critical Worldbuilding","level":"G","description":"Studies the design and analysis of invented (or constructed) worlds for narrative media, such as television, films, comics, and literary texts. Provides the practical, historical and critical tools with which to understand the function and structure of imagined worlds. Examines world-building strategies in the various media and genres in order to develop a critical and creative repertoire. Participants create their own invented worlds. Students taking graduate version complete additional assignments. Limited to 13.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"4-257"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.807"},{"code":"CMS.827","title":"Imagination, Computation, and Expression Studio","level":"G","description":"Aims to help students invent and analyze new forms of computer-based art, gaming, social media, interactive narrative, and related technologies. Students participate in a range of new and ongoing projects that are designed to hone skills in research, development, design, and evaluation. Topics vary from year to year; examples include cognitive science and artificial intelligence-based approaches to the arts; social aspects of game design; computing for social empowerment; and game character, avatar, and online profile design. May be repeated for credit with permission of instructor. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"14:00","end":"17:00","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.827"},{"code":"CMS.830","title":"Studies in Film","level":"G","description":"Intensive study of films from particular periods, genres, or directors, or films focusing on specific formal or theoretical problems. Previous topics include The Contemporary Horror Film, Film Remixes, Film Narrative, Heroic Cinema, and Color in Film. Students taking graduate version complete different assignments. May be repeated for credit with permission of instructor if content differs. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"17:00","room":"2-143"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.830"},{"code":"CMS.836","title":"Social Justice and The Documentary Film","level":"G","description":"Explores the history and current state of social-issue documentary. Examines how cultural and political upheaval and technological change have converged at different moments to bring about new waves of activist documentary film production. Particular focus on films and other non-fiction media of the present and recent past. Students screen and analyze a series of key films and work in groups to produce their own short documentary using digital video and computer-based editing. Students taking graduate version complete additional assignments. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"19:00","end":"22:00","room":"14N-112"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.836"},{"code":"CMS.840","title":"Literature and Film","level":"G","description":"Investigates relationships between the two media, including film adaptations as well as works linked by genre, topic, and style. Explores how artworks challenge and cross cultural, political, and aesthetic boundaries. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"22:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.840"},{"code":"CMS.841","title":"Game Studies","level":"G","description":"Introduction to the interdisciplinary study of videogames as texts through an examination of their cultural, educational, and social functions in contemporary settings. Students play and analyze videogames while reading current research and theory from a variety of sources in the sciences, social sciences, humanities, and industry. Assignments focus on game analysis in the context of the theories discussed in class. Includes regular reading, writing, and presentation exercises. No prior programming experience required. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.841"},{"code":"CMS.848","title":"Apocalyptic Storytelling","level":"G","description":"Focuses on the critical making of apocalyptic, post-apocalyptic and dystopian stories across various narrative media. Considers the long history of Western apocalypticism as well as the uses and abuses of apocalypticism across time. Examines a wide variety of influential texts in order to enhance students' creative and theoretical repertoires. Students create their own apocalyptic stories and present on selected texts. Investigates conventions such as plague, zombies, nuclear destruction, robot uprising, alien invasion, environmental collapse, and supernatural calamities. Considers questions of race, gender, sexuality, colonialism, trauma, memory, witness, and genocide. Intended for students with prior creative writing experience. Students taking graduate version complete additional assignments. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"16:00","room":"5-233"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.848"},{"code":"CMS.867","title":"Critical Internet Studies","level":"G","description":"Focuses on the power dynamics in internet-related technologies (including social networking platforms, surveillance technology, entertainment technologies, and emerging media forms). Theories and readings focus on the cultural, social, economic, and political aspects of internet use and design, with a special attention to gender and race. Topics include: online communication and communities, algorithms and search engines, activism and online resistance, surveillance and privacy, content moderation and platform governance, and the spread of dis- and misinformation. Instruction and practice in written and oral communication provided. Students taking the graduate version complete additional readings and assignments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"17:00","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.867"},{"code":"CMS.875","title":"Reading Climate Through Media","level":"G","description":"Explores how climate is construed in the contemporary media in order to gain a better understanding of how views of climate change are shaped and received in the public sphere. Studies the pathways that take us from climate science to media content, from the big data of global scale to the particulars and narratives of the human experience. Surveys a variety of media forms--reports, articles, comics, videos, films, photography, poetry and fiction--that reflect on the contemporary human challenges of dealing with a changing natural environment of our own making. Emphasizes the role of media in shaping public opinion, both in the US and globally, and its influence on public (and voter) perceptions on which a vast body of regulation and funding for environmental management is based. Students work individually and in teams to produce a selection of the media forms studied. Students taking graduate version complete additional assignments. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.875"},{"code":"CMS.876","title":"History of Media and Technology","level":"G","description":"Surveys the interrelated histories of communications media and technological development, from the emergence of 19th-century forms of mass print media and telegraphy, to sound capture and image-based forms (e.g., film, radio, and television), to the shift from analog to digital cultures. Examines how new forms of communication exert social, political, and cultural influences in the global context. Explores how technological innovation and accelerating media affect social values and behaviors in the popular and global adoption of a media device. Includes two papers and a research project on aspects of media history. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"19:00","end":"22:00","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.876"},{"code":"CMS.881","title":"The Algorithmic Eye: Computing and Visual Media","level":"G","description":"Studies how the use of computers to produce, capture, and comprehend views of the world has transformed visual culture. Tracks the development of computational imaging across media history (from art, photography, and film to videogames and computer vision). Students uncover the cultural stakes of computational imaging when it comes to questions of aesthetics, surveillance, automation, and infrastructure. Instruction and practice in oral and written communication provided. Students taking graduate version complete additional assignments.  Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"14E-310"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.881"},{"code":"CMS.894","title":"Education Technology Studio","level":"G","description":"Uses media and technology to develop new forms of learning experiences for schools, workplace, and informal settings. Students participate in a range of projects that hone understanding and skills in learning science, instructional design, development, and evaluation. Topics vary but include developing new media and activities for massive open online courses, creating practice spaces for practitioners in the professions and humanities, and developing new approaches to assessment in complex learning environments. May be repeated for credit with permission of instructor if project content differs. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"E15-335"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.894"},{"code":"CMS.895","title":"Learning, Media, and Technology","level":"G","description":"Addresses new digital technologies that are transforming learning across the lifespan - from reading apps for toddlers, intelligent tutors for school children, and blended learning for college students, to MOOCs for adults and interest-based learning communities for hobbyists. Focuses on how these technologies shape people's lives and learning. Students explore how education technologies operate in complex social-technical systems, and acquire analytic tools and strategies that can be applied to other complex systems. They also refine their thinking about the opportunities, limits, and tradeoffs of educational technology. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"56-191"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.895"},{"code":"CMS.901","title":"Current Debates in Media","level":"G","description":"Addresses important, current debates in media with in-depth discussion of popular perceptions and policy implications. Students use multiple perspectives to analyze texts emanating from these debates, and present their findings through discussions and reports. Explores emerging topics (e.g., piracy and IP regimes, net neutrality, media effects, social media and social change, and changing literacies) across media forms and from various historical, transcultural, and methodological perspectives. Examines the framing of these issues, their ethical and policy implications, and strategies for repositioning the debate. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"5-231"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.901"},{"code":"CMS.942","title":"Designing Virtual Worlds","level":"G","description":"Three primary areas of focus are: creating new Virtual Reality experiences; mapping the state of emerging tools; and hosting guests ? leaders in the VR/XR community, who serve as coaches for projects. Students have significant leeway to customize their own learning environment. As the field is rapidly evolving, each semester focuses on a new aspect of virtual worlds, based on the current state of innovations. Students work in teams of interdisciplinary peers from Berklee College of Music and Harvard University. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:30","end":"16:30","room":"3-370"}]},{"type":"Recitation","options":[{"days":["T"],"start":"19:00","end":"20:00","room":"9-152"},{"days":["W"],"start":"19:00","end":"20:00","room":"9-152"}]}],"url":"http://student.mit.edu/catalog/mCMSa.html#CMS.942"},{"code":"CSB.100","title":"Topics in Computational and Systems Biology","level":"G","description":"Seminar based on research literature. Papers covered are selected to illustrate important problems and varied approaches in the field of computational and systems biology, and to provide students a framework from which to evaluate new developments. Preference to first-year CSB PhD students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"11:00","end":"13:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/mCSBa.html#CSB.100"},{"code":"CSB.930","title":"Research Experience in Biopharma","level":"G","description":"Provides exposure to industrial science and develops skills necessary for success in such an environment. Under the guidance of an industrial mentor, students participate in on-site research at a local biopharmaceutical company where they observe and participate in industrial science. Serves as a real-time case study to internalize the factors that shape R&D in industry, including the purpose and scope of a project, key decision points in the past and future, and strategies for execution. Students utilize company resources and work with a scientific team to contribute to the goals of their assigned project; they then present project results to the company and class, emphasizing the logic that dictated their work and their ideas for future directions. Lecture component focuses on professional development. Enrollment may be limited based on availability of internship opportunities. Open to MIT students only.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"11:00","end":"12:00","room":"16-220"}]}],"url":"http://student.mit.edu/catalog/mCSBa.html#CSB.930"},{"code":"CSE.C20","title":"Introduction to Computational Science and Engineering","level":"U","description":"Provides an introduction to computational algorithms used throughout engineering and science (natural and social) to simulate time-dependent phenomena; optimize and control systems; and quantify uncertainty in problems involving randomness, including an introduction to probability and statistics. Combination of 6.100A and 16.C20J counts as REST subject.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:30","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/mCSEa.html#CSE.C20"},{"code":"EC.050","title":"Re-create Experiments from History: Inform the Future from the Past","level":"U","description":"Offers students alternative exploratory experience in teaching, learning, and researching. Through collaborative activities with open-ended experiments from diverse origins, participants re-create historical instruments and discoveries that challenged assumptions and sparked new investigations. Student curiosity and questions shape specific course content. Assignments include observations, experiments, readings, journal writing and sketching, and a final reflective paper. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"4-402"}]},{"type":"Lab","options":[{"days":["R"],"start":"15:00","end":"17:00","room":"4-402"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.050"},{"code":"EC.090","title":"Re-create Experiments from History: Inform the Future from the Past","level":"G","description":"Offers students alternative exploratory experience in teaching, learning, and researching. Through collaborative activities with open-ended experiments from diverse origins, participants re-create historical instruments and discoveries that challenged assumptions and sparked new investigations. Student curiosity and questions shape specific course content. Assignments include observations, experiments, readings, journal writing and sketching, and a final reflective paper. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"4-402"}]},{"type":"Lab","options":[{"days":["R"],"start":"15:00","end":"17:00","room":"4-402"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.090"},{"code":"EC.120","title":"Electronics Project Laboratory","level":"U","description":"Intuition-based introduction to electronics, electronic components, and test equipment such as oscilloscopes, multimeters, and signal generators. Key components studied and used are op-amps, comparators, bi-polar transistors, and diodes (including LEDs). Students design, build, and debug small electronics projects (often featuring sound and light) to put their new knowledge into practice. Upon completing the class, students can take home a kit of components. Intended for students with little or no previous background in electronics. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"4-409"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.120"},{"code":"EC.701","title":"D-Lab: Development","level":"U","description":"Issues in international development, appropriate technology and project implementation addressed through lectures, case studies, guest speakers and laboratory exercises. Students form project teams to partner with community organizations in developing countries, and formulate plans for an optional IAP site visit. (Previous field sites include Ghana, Brazil, Honduras and India.) Recitation sections focus on specific project implementation, and include cultural, social, political, environmental and economic overviews of the target countries as well as an introduction to the local languages. Enrollment limited by lottery; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["F"],"start":"15:30","end":"17:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.701"},{"code":"EC.712","title":"Applications of Energy in Global Development","level":"U","description":"Engages students in project-based learning, in collaboration with D-Lab community partners, to improve access to affordable, reliable, sustainable, and modern energy for all. Teams work on off-grid energy projects addressing challenges in lighting, cooking, agricultural productivity, or other areas in collaboration with D-Lab community partners in developing countries. Project work includes assessment of user needs, technology identification, product design, prototyping, and development of implementation strategies to continue progress of ongoing projects. Optional IAP field visits may be available to test and implement the solutions developed during the semester. Students enrolled in the graduate version complete additional assignments.  Limited to 20; preference to students who have taken EC.711.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"15:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.712"},{"code":"EC.718","title":"D-Lab: Gender and Development","level":"U","description":"Explores gender roles, illuminates the power dynamics and root causes of inequality, and provides a framework for understanding gender dynamics. Develops skills to conduct a gender analysis and integrate gender-sensitive strategies into large- and small-scale development solutions. Prompts critical discussion about social, economic, and political conditions that shape gender in development. Begins with exploration of international development in the post-colonial era, using a gender lens, then provides students with the tools to integrate gender-sensitive strategies into international development work, with a particular focus on launching, building and scaling women's ventures. Opportunities may be available for international fieldwork over IAP. Meets with 24.234 when offered concurrently. Students taking graduate version complete additional assignments. Limited to 12; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.718"},{"code":"EC.729","title":"D-Lab: Design for Scale","level":"U","description":"Explores the external factors affecting product development for people in low-resource settings in a project-based context. Students apply existing engineering skills in interdisciplinary teams to identify contextual limitations and develop previously established prototypes towards manufacturing-ready product designs for real-world project sponsors. Topics are presented within the context of the developing world and include technology feasibility and scalability assessment; value chain analysis; product specification; and manufacturing methodologies at various scales. Lessons are experiential and case study-based, taught by instructors with field experience and industry experts from product development consulting firms and the consumer electronics industry. Students taking graduate version complete additional written assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["R"],"start":"14:00","end":"15:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.729"},{"code":"EC.750","title":"Humanitarian Innovation: Design for Relief, Rebuilding, and Recovery","level":"U","description":"Explores the role innovation can and does play in how humanitarian aid is provided, and how it can impact people, products, and processes. Provides a fundamental background in the history and practice of humanitarian aid. Considers the various ways that design can be used to enhance aid, such as product and system design for affected populations, co-creation with affected populations, and capacity building to promote design by refugees and the displaced. Case studies and projects examine protracted displacement as well as recovery and resettlement, including efforts in Colombia, Lebanon, Nepal, Sudan, and Uganda. Potential for students to travel over the summer to partner communities.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"15:00","room":"N51-350"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.750"},{"code":"EC.781","title":"D-Lab: Development","level":"G","description":"Issues in international development, appropriate technology and project implementation addressed through lectures, case studies, guest speakers and laboratory exercises. Students form project teams to partner with community organizations in developing countries, and formulate plans for an optional IAP site visit. (Previous field sites include Ghana, Brazil, Honduras and India.) Recitation sections focus on specific project implementation, and include cultural, social, political, environmental and economic overviews of the target countries as well as an introduction to the local languages. Enrollment limited by lottery; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["F"],"start":"15:30","end":"17:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.781"},{"code":"EC.782","title":"Applications of Energy in Global Development","level":"G","description":"Engages students in project-based learning in collaboration with D-Lab community partners to improve access to affordable, reliable, sustainable, and modern energy for all. Teams work on off-grid energy projects addressing challenges in lighting, cooking, agricultural productivity, or other areas in collaboration with D-Lab community partners in developing countries. Project work includes assessment of user needs, technology identification, product design, prototyping, and development of implementation strategies to continue progress of ongoing projects. Optional IAP field visits may be available to test and implement the solutions developed during the semester. Students enrolled in the graduate version complete additional assignments.  Limited to 20; preference to students who have taken EC.791.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"15:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.782"},{"code":"EC.785","title":"Humanitarian Innovation: Design for Relief, Rebuilding, and Recovery","level":"G","description":"Explores the role innovation can and does play in how humanitarian aid is provided, and how it can impact people, products, and processes. Provides a fundamental background in the history and practice of humanitarian aid. Considers the various ways that design can be used to enhance aid, such as product and system design for affected populations, co-creation with affected populations, and capacity building to promote design by refugees and the displaced. Case studies and projects examine protracted displacement as well as recovery and resettlement, including efforts in Colombia, Lebanon, Nepal, Sudan, and Uganda. Potential for students to travel over the summer to partner communities.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"15:00","room":"N51-350"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.785"},{"code":"EC.797","title":"D-Lab: Design for Scale","level":"G","description":"Explores the external factors affecting product development for people in low-resource settings in a project-based context. Students apply existing engineering skills in interdisciplinary teams to identify contextual limitations and develop previously established prototypes towards manufacturing-ready product designs for real-world project sponsors. Topics are presented within the context of the developing world and include technology feasibility and scalability assessment; value chain analysis; product specification; and manufacturing methodologies at various scales. Lessons are experiential and case study-based, taught by instructors with field experience and industry experts from product development consulting firms and the consumer electronics industry. Students taking graduate version complete additional written assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["R"],"start":"14:00","end":"15:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.797"},{"code":"EC.798","title":"D-Lab: Gender and Development","level":"G","description":"Explores gender roles, illuminates the power dynamics and root causes of inequality, and provides a framework for understanding gender dynamics. Develops skills to conduct a gender analysis and integrate gender-sensitive strategies into large- and small-scale development solutions. Prompts critical discussion about social, economic, and political conditions that shape gender in development. Begins with exploration of international development in the post-colonial era, using a gender lens, then provides students with the tools to integrate gender-sensitive strategies into international development work, with a particular focus on launching, building and scaling women's ventures. Opportunities may be available for international fieldwork over IAP. Meets with 24.634 when offered concurrently. Students taking graduate version complete additional assignments. Limited to 12; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mECa.html#EC.798"},{"code":"EM.411","title":"Foundations of System Design and Management I","level":"G","description":"Presents the foundations of systems architecture, systems engineering and project management in an integrated format, through a synchronized combination of in-class discussion, industrial guest speakers, team projects, and individual assignments. Topics include stakeholder analysis, project planning and monitoring, requirements definition, concept generation and selection, complexity management, system integration, verification and validation, cost modeling, systems safety, organizational design and effective teamwork, risk management, and leadership styles. Restricted to students in the SDM program.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"13:00","room":"1-390"}]},{"type":"Recitation","options":[{"days":["T","R"],"start":"12:00","end":"13:00","room":"1-390"},{"days":["T","R"],"start":"13:00","end":"14:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mEMa.html#EM.411"},{"code":"EM.415","title":"SDM Research and Thesis Seminar","level":"G","description":"Introduces practical principles, methods, and tools of research and thesis preparation for engineers and managers. Topics include: thesis formulation, abstract and proposal writing, literature search and review, data collection, modeling, construction of argument, time budgeting, and research presentation. Through a sequence of structured assignments building toward a mock thesis proposal, students develop skills in scoping a research question, identifying and evaluating sources, planning data collection, budgeting time and resources, and pitching their work to potential advisors. Culminates in a mock thesis proposal presentation and pitch to experienced SDM thesis advisors. Priority to SDM students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"12:00","end":"13:00","room":"E51-395"}]}],"url":"http://student.mit.edu/catalog/mEMa.html#EM.415"},{"code":"EM.420","title":"Model-based Engineering in the Product Development Lifecycle","level":"G","description":"Explores the application of digital design tools in a digital thread of linked applications and a common data structure. Investigates how this environment may improve productivity, collaboration, decision-making, and innovation in product development. Students use industry-standard digital methods and tools to create key design artifacts in a product development project. Periodic design reviews assess design evolution and progress. Students use processes for requirements traceability and management, configuration control, and engineering change management in a multidisciplinary team setting. Concludes with an examination of digital transformation, exploring concepts such as digital thread and digital twins. Students analyze both the opportunities and challenges in digital transformation, including the strategic implementation and potential pitfalls of using model-based engineering methods and tools.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:30","end":"16:00","room":"2-131"}]},{"type":"Recitation","options":[{"days":["R"],"start":"16:00","end":"17:00","room":"2-131"}]}],"url":"http://student.mit.edu/catalog/mEMa.html#EM.420"},{"code":"EM.422","title":"System Design and Management for a Changing World: Combined","level":"G","description":"Practical-oriented subject that builds upon theory and methods and culminates in extended application. Covers methods to identify, value, and implement flexibility in design (real options). Topics include definition of uncertainties, simulation of performance for scenarios, screening models to identify desirable flexibility, decision analysis, and multidimensional economic evaluation. Students demonstrate proficiency through an extended application to a system design of their choice. Complements research or thesis projects. Class is 'flipped' to maximize student engagement and learning. Meets with IDS.333 in the first half of term. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mEMa.html#EM.422"},{"code":"EM.423","title":"System Design and Management for a Changing World: Tools","level":"G","description":"Focuses on design choices and decisions under uncertainty. Topics include identification and description of uncertainties using probability distributions; the calculation of commensurate measures of value, such as expected net present values; Monte Carlo simulation and risk analysis; and the use of decision analysis to explore alternative strategies and identify optimal initial choices. Presents applied analysis of practical examples from a variety of engineering systems using spreadsheet and decision analysis software. Class is 'flipped' to maximize student engagement and learning. Meets with IDS.332 first half of term.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mEMa.html#EM.423"},{"code":"EM.424","title":"System Design and Management for a Changing World: Projects","level":"G","description":"Focuses on implementation of flexibility (real options) in the design of products, start-ups, ongoing management of operations, or policy plans. Applies the methods presented in IDS.333: recognition of uncertainty, identification of best opportunities for flexibility, and valuation of these options and their effective implementation. Students work on their own project concept, for which they develop a dynamic business plan for design, deployment, and most beneficial implementation of their system over time. Useful complement to thesis or research projects. Class is 'flipped' to maximize student engagement and learning. Subject meets in second half of term in the fall and first half of term in the spring.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mEMa.html#EM.424"},{"code":"EM.425","title":"Research Seminar on Engineering Projects and Teamwork","level":"G","description":"Review of research on engineering as work and problem-solving by teams, including cases, professional practices, experimental results, and teamwork fundamentals. Topics include: projects structures and dependence; communication, coordination, and concurrency; exception handling, rework, and quality; awareness, attention, and engagement; and information, uncertainty, and learning. Students consider engineering teamwork phenomena which integrate technical and organizational aspects, leading to insights on performance during project shaping, ideation, planning, control, adaptation, and lessons learned. In the second half, students work as small teams to propose an experiment which explores teamwork during engineering. Proposed experiments often become basis for research and thesis activity.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"17:00","end":"18:30","room":"E51-372"}]}],"url":"http://student.mit.edu/catalog/mEMa.html#EM.425"},{"code":"EM.431","title":"Applied Category Theory for Engineering Design","level":"G","description":"Considers the multiple trade-offs at various abstraction levels and scales when designing complex, multi-component systems. Covers topics from foundational principles to advanced applications, emphasizing the role of compositional thinking in engineering. Introduces category theory as a mathematical framework for abstraction and composition, enabling a unified and modular approach to modeling, analyzing, and designing interconnected systems. Showcases successful applications in areas such as dynamical systems and automated system design optimization, with a focus on autonomous robotics and mobility. Offers students the opportunity to work on their own application through a dedicated project in the second half of the term. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-234"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/mEMa.html#EM.431"},{"code":"ES.1801","title":"Calculus","level":"U","description":"Equivalent to 18.01; see 18.01 for description. Instruction provided through small, interactive classes. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"11:00","end":"12:00","room":"24-611A"}]},{"type":"Recitation","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"24-619"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.1801"},{"code":"ES.1802","title":"Calculus","level":"U","description":"Equivalent to 18.02; see 18.02 for description. Instruction provided through small, interactive classes. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R"],"start":"12:00","end":"13:00","room":"24-618"},{"days":["M","T","W","R"],"start":"13:00","end":"14:00","room":"24-618"},{"days":["M","T","W","R"],"start":"14:00","end":"15:00","room":"24-618"}]},{"type":"Recitation","options":[{"days":["R"],"start":"16:00","end":"17:00","room":"24-618"},{"days":["F"],"start":"09:00","end":"10:00","room":"24-618"},{"days":["F"],"start":"12:00","end":"13:00","room":"24-618"},{"days":["F"],"start":"14:00","end":"15:00","room":"24-618"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.1802"},{"code":"ES.1803","title":"Differential Equations","level":"U","description":"Equivalent to 18.03; see 18.03 for description. Instruction provided through small, interactive classes. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R","F"],"start":"11:00","end":"12:00","room":"24-618"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.1803"},{"code":"ES.181A","title":"Calculus","level":"U","description":"Equivalent to 18.01A; see 18.01A for description. Instruction provided through small, interactive classes. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R","F"],"start":"10:00","end":"11:00","room":"24-618"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.181A"},{"code":"ES.182A","title":"Calculus","level":"U","description":"Equivalent to 18.02A; see 18.02A for description. Instruction provided through small, interactive classes. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R","F"],"start":"10:00","end":"11:00","room":"24-618"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.182A"},{"code":"ES.200","title":"ESG Undergraduate Teaching","level":"U","description":"An opportunity to assist in the teaching of subjects in ESG in biology, chemistry, humanities and social sciences, mathematics, and physics. Student instructors may be involved in grading, running problemsolving sessions, or teaching classes depending on experience and interest. Qualified students may also develop and teach undergraduate seminars under the supervision of an appropriate faculty or staff member. Student instructors meet weekly with staff to discuss their teaching and cover a variety of topics related to effective teaching techniques. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"17:00","room":"24-619"},{"days":["F"],"start":"16:00","end":"17:00","room":"24-619"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.200"},{"code":"ES.5111","title":"Principles of Chemical Science","level":"U","description":"Equivalent to 5.111; see 5.111 for description. Instruction provided through small, interactive classes taught by ESG staff. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R","F"],"start":"09:00","end":"10:00","room":"24-619"},{"days":["M","T","W","R","F"],"start":"10:00","end":"11:00","room":"24-619"},{"days":["M","T","W","R","F"],"start":"14:00","end":"15:00","room":"24-619"},{"days":["M","T","W","R","F"],"start":"15:00","end":"16:00","room":"24-619"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.5111"},{"code":"ES.801","title":"Physics I","level":"U","description":"Equivalent to 8.01; see 8.01 for description. Instruction provided through small, interactive classes. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["M","T","W","R","F"],"start":"10:00","end":"11:00","room":"24-621"},{"days":["M","T","W","R","F"],"start":"11:00","end":"12:00","room":"24-621"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.801"},{"code":"ES.8012","title":"Physics I","level":"U","description":"Equivalent to 8.012; see 8.012 for description. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"12:00","end":"14:00","room":"24-611A"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.8012"},{"code":"ES.8022","title":"Physics II","level":"U","description":"Equivalent to 8.022; see 8.022 for description. Students complete group projects. Some content is decided by students. Limited to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:00","end":"14:00","room":"24-611A"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.8022"},{"code":"ES.9114","title":"Non-violence as a Way of Life - MIT Prison Initiative","level":"U","description":"Addresses the philosophical question of what a non-violent life entails. Investigates its ethical dimensions and challenges, and considers whether we can derive a comprehensive moral theory from the principle of non-violence. Discusses the issues of lying, the duty to forgive, non-violent communication, the ethics of our relationship to anger, the possibility of loving enemies, and the ethics of punishment and rehabilitation.  Includes readings from primary exponents of non-violence, such as Tolstoy, Gandhi and King. Taught inside a secure Massachusetts correctional facility with a mix of MIT students and incarcerated students. Limited to 10.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"20:30","room":"BOSTON PRE-REL"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.9114"},{"code":"ES.92","title":"Authenticity - MIT Prison Initiative","level":"U","description":"Explores the question of how to live an authentic life, through works of western and eastern philosophy and contemporary psychology. Topics include emotions, anger, honesty, forgiveness, non-violent communication, conflict resolution, kindness and cruelty and compassion. Taught inside a secure Massachusetts correctional facility with a mix of MIT students and incarcerated students. Limited to 12.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"15:00","room":"SUFFOLK COUNTY"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.92"},{"code":"ES.S70","title":"Special Seminar in Interdisciplinary Studies","level":"U","description":"Covers topics not included in the permanent curriculum. May not be used for GIR credit, but may be repeated for credit with permission of instructor. Preference to students in ESG.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"17:00","room":"24-621"}]}],"url":"http://student.mit.edu/catalog/mESa.html#ES.S70"},{"code":"HST.010","title":"Human Functional Anatomy","level":"G","description":"Lectures, detailed laboratory dissections, and prosections provide a thorough exploration of the gross structure and function of the human body. Fundamental principles of bioengineering are employed to promote analytical approaches to understanding the body's design. The embryology of major organ systems is presented, together with certain references to phylogenetic development, as a basis for comprehending anatomical complexity. Correlation clinics stress both normal and abnormal functions of the body and present evolving knowledge of genes responsible for normal and abnormal anatomy. Lecturers focus on current problems in organ system research. Only HST students may register under HST.010, graded P/D/F. Lab fee.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:30","end":"16:30","room":"MEC-TBD"}]},{"type":"Lab","options":[{"days":["R"],"start":"16:00","end":"17:00","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.010"},{"code":"HST.011","title":"Human Functional Anatomy","level":"G","description":"Lectures, detailed laboratory dissections, and prosections provide a thorough exploration of the gross structure and function of the human body. Fundamental principles of bioengineering are employed to promote analytical approaches to understanding the body's design. The embryology of major organ systems is presented, together with certain references to phylogenetic development, as a basis for comprehending anatomical complexity. Correlation clinics stress both normal and abnormal functions of the body and present evolving knowledge of genes responsible for normal and abnormal anatomy. Lecturers focus on current problems in organ system research. Only HST students may register under HST.010, graded P/D/F. Lab fee. Enrollment restricted to graduate students.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"12:30","end":"16:30","room":"MEC-TBD"}]},{"type":"Lab","options":[{"days":["R"],"start":"16:00","end":"17:00","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.011"},{"code":"HST.022","title":"Integrations & Innovation in Medical Sciences I","level":"G","description":"Provides instruction in applying basic science to clinical reasoning, as well as communication and interpersonal skills in interacting with patients. Includes interactive case-based discussions, journal clubs, patient visits, and expert panels and guest speakers to explore the interdisciplinary topics and uncertainty in medicine. Restricted to first-year HST MD students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"08:30","end":"12:30","room":"E25-117"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.022"},{"code":"HST.030","title":"Human Pathology","level":"G","description":"Introduction to the functional structure of normal cells and tissues; pathologic principles of cellular adaptation and injury, inflammation, circulatory disorders, immunologic injury, infection, genetic disorders, and neoplasia in humans. Lectures, conferences emphasizing clinical correlations and contemporary experimental biology, laboratories with examination of microscopic and gross specimens, and autopsy case studies emphasizing modern pathology practice. Only HST students may register under HST.030, graded P/D/F. Lab fee. Limited to 60; priority to HST students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"11:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.030"},{"code":"HST.031","title":"Human Pathology","level":"G","description":"Introduction to the functional structure of normal cells and tissues, pathologic principles of cellular adaptation and injury, inflammation, circulatory disorders, immunologic injury, infection, genetic disorders, and neoplasia in humans. Lectures, conferences emphasizing clinical correlations and contemporary experimental biology. Laboratories with examination of microscopic and gross specimens, and autopsy case studies emphasizing modern pathology practice. Only HST students may register under HST.030, graded P/D/F. Lab fee. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"11:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.031"},{"code":"HST.040","title":"Mechanisms of Microbial Pathogenesis","level":"G","description":"Deals with the mechanisms of pathogenesis of bacteria, viruses, and other microorganisms. Approach spans mechanisms from molecular to clinical aspects of disease. Topics selected for intrinsic interest and cover the demonstrated spectrum of pathophysiologic mechanisms. Only HST students may register under HST.040, graded P/D/F. Lab fee. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"10:30","end":"12:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.041"},{"code":"HST.041","title":"Mechanisms of Microbial Pathogenesis","level":"G","description":"Deals with the mechanisms of pathogenesis of bacteria, viruses, and other microorganisms. Approach spans mechanisms from molecular to clinical aspects of disease. Topics selected for intrinsic interest and cover the demonstrated spectrum of pathophysiologic mechanisms. Only HST students may register under HST.040, graded P/D/F. Lab fee. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"10:30","end":"12:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.041"},{"code":"HST.070","title":"Human Reproductive Biology","level":"G","description":"Lectures and clinical case discussions designed to provide the student with a clear understanding of the physiology, endocrinology, and pathology of human reproduction. Emphasis is on the role of technology in reproductive science. Suggestions for future research contributions in the field are probed. Students become involved in the wider aspects of reproduction, such as prenatal diagnosis, in vitro fertilization, abortion, menopause, contraception and ethics relation to reproductive science. Only HST students may register under HST.070, graded P/D/F.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"17:30","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.071"},{"code":"HST.071","title":"Human Reproductive Biology","level":"G","description":"Lectures and clinical case discussions designed to provide the student with a clear understanding of the physiology, endocrinology, and pathology of human reproduction. Emphasis is on the role of technology in reproductive science. Suggestions for future research contributions in the field are probed. Students become involved in the wider aspects of reproduction, such as prenatal diagnosis, in vitro fertilization, abortion, menopause, contraception and ethics relation to reproductive science. Only HST students may register under HST.070, graded P/D/F.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"17:30","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.071"},{"code":"HST.120","title":"Gastroenterology","level":"G","description":"Presents the anatomy, physiology, biochemistry, biophysics, and bioengineering of the gastrointestinal tract and associated pancreatic, liver, and biliary systems. Emphasis on the molecular and pathophysiological basis of disease where known. Covers gross and microscopic pathology and clinical aspects. Formal lectures given by core faculty, with some guest lectures by local experts. Selected seminars conducted by students with supervision of faculty. Only HST students may register under HST.120, graded P/D/F. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:30","end":"17:00","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.121"},{"code":"HST.121","title":"Gastroenterology","level":"G","description":"Presents the anatomy, physiology, biochemistry, biophysics, and bioengineering of the gastrointestinal tract and associated pancreatic, liver, and biliary systems. Emphasis on the molecular and pathophysiological basis of disease where known. Covers gross and microscopic pathology and clinical aspects. Formal lectures given by core faculty, with some guest lectures by local experts. Selected seminars conducted by students with supervision of faculty. Only HST students may register under HST.120, graded P/D/F. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:30","end":"17:00","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.121"},{"code":"HST.130","title":"Neuroscience","level":"G","description":"Comprehensive study of neuroscience where students explore the brain on levels ranging from molecules and cells through neural systems, perception, memory, and behavior. Includes some aspects of clinical neuroscience, within neuropharmacology, pathophysiology, and neurology. Lectures supplemented by conferences and labs. Labs review neuroanatomy at the gross and microscopic levels. Limited to 50 HST students.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"08:00","end":"12:30","room":"MEC-TBD"}]},{"type":"Recitation","options":[{"days":["F"],"start":"08:00","end":"09:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.130"},{"code":"HST.131","title":"Neuroscience","level":"G","description":"Comprehensive study of neuroscience where students explore the brain on levels ranging from molecules and cells through neural systems, perception, memory, and behavior. Includes some aspects of clinical neuroscience, within neuropharmacology, pathophysiology, and neurology. Lectures supplemented by conferences and labs. Labs review neuroanatomy at the gross and microscopic levels. Only HST students may register under HST.130, graded P/D/F. Limited to 50.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"08:00","end":"12:30","room":"MEC-TBD"}]},{"type":"Recitation","options":[{"days":["F"],"start":"08:00","end":"09:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.131"},{"code":"HST.146","title":"Biochemistry and Metabolism","level":"G","description":"First-year graduate level intensive subject in human biochemistry and physiological chemistry that focuses on intermediary metabolism, structures of key intermediates and enzymes important in human disease. Subject is divided into four areas: carbohydrates, lipids, amino acids and nucleic acids. The importance of these areas is underscored with examples from diseases and clinical correlations. Preparatory sessions meet in August. Only HST students may register under HST.146, graded P/D/F. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"12:30","end":"15:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.147"},{"code":"HST.147","title":"Biochemistry and Metabolism","level":"G","description":"First-year graduate level intensive subject in human biochemistry and physiological chemistry that focuses on intermediary metabolism, structures of key intermediates and enzymes important in human disease. Subject is divided into four areas: carbohydrates, lipids, amino acids and nucleic acids. The importance of these areas is underscored with examples from diseases and clinical correlations. Preparatory sessions meet in August. Only HST students may register under HST.146, graded P/D/F. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"12:30","end":"15:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.147"},{"code":"HST.150","title":"Principles of Pharmacology","level":"G","description":"Covers both general pharmacological principles (pharmacodynamics, toxicology, pharmacokinetics, pharmacogenetics, drug interactions, pharmacoepidemiology, pharmaco-economics, and the placebo effect), and important clinical pharmacology areas (anti-microbials, general anesthetics, local anesthetics, autonomic modulation, anti-dysrhythmics, hypertension, heart failure, diabetes, anti-inflammatory drugs for rheumatology, immunomodulation for organ transplant, cancer chemotherapy, neuropsychopharmacology, opioids and opioid use disorder, cannabinoids, and drug delivery engineering). In addition, students taking the subject for credit contribute to teaching by presenting and analyzing clinical cases and therapeutic strategies. Highly recommended that students have prior education in human physiology and pathophysiology. Subject follows HMS calendar. Restricted to HST MD & HST PhD students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"08:00","end":"12:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.151"},{"code":"HST.151","title":"Principles of Pharmacology","level":"G","description":"Covers both general pharmacological principles (pharmacodynamics, toxicology, pharmacokinetics, pharmacogenetics, drug interactions, pharmacoepidemiology, pharmaco-economics, and the placebo effect), and important clinical pharmacology areas (anti-microbials, general anesthetics, local anesthetics, autonomic modulation, anti-dysrhythmics, hypertension, heart failure, diabetes, anti-inflammatory drugs for rheumatology, immunomodulation for organ transplant, cancer chemotherapy, neuropsychopharmacology, opioids and opioid use disorder, cannabinoids, and drug delivery engineering). In addition, students taking the subject for credit contribute to teaching by presenting and analyzing clinical cases and therapeutic strategies. Highly recommended that students have prior education in human physiology and pathophysiology. Subject follows HMS calendar. Restricted to HST MD & HST PhD students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"08:00","end":"12:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.151"},{"code":"HST.160","title":"Genetics in Modern Medicine","level":"G","description":"Provides a foundation for understanding the relationship between molecular biology, genetics, and medicine. Starts with an introduction to molecular genetics, and quickly transitions to the genetic basis of diseases, including chromosomal, mitochondrial and epigenetic disease. Translation of clinical understanding into analysis at the level of the gene, chromosome, and molecule; the concepts and techniques of molecular biology and genomics; and the strategies and methods of genetic analysis. Includes diagnostics (prenatal and adult), cancer genetics, and the development of genetic therapies (RNA, viral, and genome editing). The clinical relevance of these areas is underscored with patient presentations. Only HST students may register under HST.160, graded P/D/F.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"12:30","end":"15:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.160"},{"code":"HST.161","title":"Genetics in Modern Medicine","level":"G","description":"Provides a foundation for understanding the relationship between molecular biology, genetics, and medicine. Starts with an introduction to molecular genetics, and quickly transitions to the genetic basis of diseases, including chromosomal, mitochondrial and epigenetic disease. Translation of clinical understanding into analysis at the level of the gene, chromosome, and molecule; the concepts and techniques of molecular biology and genomics; and the strategies and methods of genetic analysis. Includes diagnostics (prenatal and adult), cancer genetics, and the development of genetic therapies (RNA, viral, and genome editing). The clinical relevance of these areas is underscored with patient presentations. Only HST students may register under HST.160, graded P/D/F.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"12:30","end":"15:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.161"},{"code":"HST.162","title":"Molecular Diagnostics and Bioinformatics","level":"G","description":"Introduction of molecular diagnostic methods in medicine and relevant bioinformatics methods. Discussion of principles of molecular testing for diagnosis of somatic and germline diseases using FISH, classical genotyping, array CGH, next generation sequencing, and other technologies. Case conferences emphasize clinical correlation and integration of information from multiple diagnostic tests. Bioinformatics lectures, problem sets, and laboratory sessions will introduce key concepts in biological sequence analysis and provide experience with bioinformatics tools. HST.015 and HST.191 recommended. Only HST students may register under HST.162, P/D/F. Enrollment limited, preference to HST students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"12:30","end":"15:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.162"},{"code":"HST.163","title":"Molecular Diagnostics and Bioinformatics","level":"G","description":"Introduction of molecular diagnostic methods in medicine and relevant bioinformatics methods. Discussion of principles of molecular testing for diagnosis of somatic and germline diseases using FISH, classical genotyping, array CGH, next generation sequencing, and other technologies. Case conferences emphasize clinical correlation and integration of information from multiple diagnostic tests. Bioinformatics lectures, problem sets, and laboratory sessions will introduce key concepts in biological sequence analysis and provide experience with bioinformatics tools. HST.015 and HST.191 recommended. Only HST students may register under HST.162, P/D/F. Enrollment limited, preference to HST students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"12:30","end":"15:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.163"},{"code":"HST.175","title":"Cellular and Molecular Immunology","level":"G","description":"Covers cells and tissues of the immune system, lymphocyte development, the structure and function of antigen receptors, the cell biology of antigen processing and presentation including molecular structure and assembly of MHC molecules, lymphocyte activation, the biology of cytokines, leukocyte-endothelial interactions, and the pathogenesis of immunologically mediated diseases. Consists of lectures and tutorials in which clinical cases are discussed with faculty tutors. Details of each case covering a number of immunological issues in the context of disease are posted on a student website. Limited to 45.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"11:00","room":"RAGON"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.175"},{"code":"HST.176","title":"Cellular and Molecular Immunology","level":"G","description":"Covers cells and tissues of the immune system, lymphocyte development, the structure and function of antigen receptors, the cell biology of antigen processing and presentation including molecular structure and assembly of MHC molecules, lymphocyte activation, the biology of cytokines, leukocyte-endothelial interactions, and the pathogenesis of immunologically mediated diseases. Consists of lectures and tutorials in which clinical cases are discussed with faculty tutors. Details of each case covering a number of immunological issues in the context of disease are posted on a student website. Only HST students may register under HST.175, graded P/D/F. Limited to 45.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"08:30","end":"11:00","room":"RAGON"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.176"},{"code":"HST.194","title":"Clinical Epidemiology","level":"G","description":"Introduces methods for the generation, analysis, and interpretation of data for clinical research. Major topics include the design of surveys, predictive models, randomized trials, clinical cohorts, and analyses of electronic health records. Prepares students to formulate well-defined research questions, design data collection, evaluate algorithms for clinical prediction, design studies for causal inference, and identify and prevent biases in clinical research. Emphasizes critical thinking and practical applications, including daily assignments based on articles published in major clinical journals and the discussion of a case study each week. Trains students to comprehend, critique, and communicate findings from the biomedical literature. Familiarity with regression modeling and basic statistical theory is a prerequisite. Only HST students may register under HST.194, graded P/D/F. Enrollment limited; restricted to HST MD and MEMP PhD students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:30","end":"12:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.195"},{"code":"HST.195","title":"Clinical Epidemiology","level":"G","description":"Introduces methods for the generation, analysis, and interpretation of data for clinical research. Major topics include the design of surveys, predictive models, randomized trials, clinical cohorts, and analyses of electronic health records. Prepares students to formulate well-defined research questions, design data collection, evaluate algorithms for clinical prediction, design studies for causal inference, and identify and prevent biases in clinical research. Emphasizes critical thinking and practical applications, including daily assignments based on articles published in major clinical journals and the discussion of a case study each week. Trains students to comprehend, critique, and communicate findings from the biomedical literature. Familiarity with regression modeling and basic statistical theory is a prerequisite. Only HST students may register under HST.194, graded P/D/F. Enrollment limited; restricted to HST MD and MEMP PhD students.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:30","end":"12:30","room":"MEC-TBD"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.195"},{"code":"HST.452","title":"Statistical Physics in Biology","level":"G","description":"A survey of problems at the interface of statistical physics and modern biology: bioinformatic methods for extracting information content of DNA; gene finding, sequence comparison, phylogenetic trees. Physical interactions responsible for structure of biopolymers; DNA double helix, secondary structure of RNA, elements of protein folding. Considerations of force, motion, and packaging; protein motors, membranes. Collective behavior of biological elements; cellular networks, neural networks, and evolution.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"26-314"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.452"},{"code":"HST.518","title":"Human Systems Engineering","level":"G","description":"Provides a fundamental understanding of human factors that must be taken into account in the design and engineering of complex aviation, space, and medical systems. Focuses primarily on derivation of human engineering design criteria from sensory, motor, and cognitive sources. Includes principles of displays, controls and ergonomics, manual control, the nature of human error, basic experimental design, and human-computer interaction in supervisory control settings. Students taking graduate version complete a research project with a final written report and oral presentation.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"3-370"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.518"},{"code":"HST.525","title":"Tumor Microenvironment and Immuno-Oncology: A Systems Biology Approach","level":"G","description":"Provides theoretical background to analyze and synthesize the most up-to-date findings from both laboratory and clinical investigations into solid tumor pathophysiology. Covers different topics centered on the critical role that the tumor microenvironment plays in the growth, invasion, metastasis and treatment of solid tumors. Develops a systems-level, quantitative understanding of angiogenesis, extracellular matrix, metastatic process, delivery of drugs and immune cells, and response to conventional and novel therapies, including immunotherapies. Discussions provide critical comments on the challenges and the future opportunities in research on cancer and in establishment of novel therapeutic approaches and biomarkers to guide treatment.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"17:00","end":"19:00","room":"E25-111"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.525"},{"code":"HST.535","title":"Tissue Engineering and Organ Regeneration","level":"G","description":"Principles and practice of tissue engineering (TE) and organ regeneration (OR). Topics include: cellular/molecular processes that induce fibrosis following traumatic injury, surgical excision, disease, and aging; targets for treatment for induced regeneration; and the tools that can be used to formulate the treatments. Presents the basic science of organ regeneration. Principles underlying engineering strategies for employing select implantable or injectable biomaterial scaffolds, exogenous cells or their organelles, and drugs or regulatory molecules, for the formation of tissue in vitro (TE) and regeneration of tissues/organs in vivo (OR). Describes the technologies for producing biomaterial scaffolds and for incorporating cells and regulatory molecules into workable devices. Examples of clinical successes and failures of regenerative devices are analyzed as case studies.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"5-134"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.535"},{"code":"HST.540","title":"Human Physiology","level":"U","description":"Comprehensive exploration of human physiology, emphasizing the molecular basis and applied aspects of organ function and regulation in health and disease. Includes a review of cell structure and function, as well as the mechanisms by which the endocrine and nervous systems integrate cellular metabolism. Special emphasis on examining the cardiovascular, pulmonary, gastrointestinal, renal, reproductive, and muscular skeletal systems, as well as liver function, drug metabolism, and pharmacogenetics.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:00","end":"11:00","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["T"],"start":"19:30","end":"20:30","room":"26-328"},{"days":["W"],"start":"11:00","end":"12:00","room":"26-328"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.540"},{"code":"HST.542","title":"Quantitative and Clinical Physiology","level":"U","description":"Application of the principles of energy and mass flow to major human organ systems. Anatomical, physiological and clinical features of the cardiovascular, respiratory and renal systems. Mechanisms of regulation and homeostasis. Systems, features and devices that are most illuminated by the methods of physical sciences and engineering models. Required laboratory work includes animal studies. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"4-265"}]},{"type":"Recitation","options":[{"days":["W"],"start":"13:00","end":"14:00","room":"34-301"},{"days":["W"],"start":"14:00","end":"15:00","room":"34-301"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.542"},{"code":"HST.583","title":"Functional Magnetic Resonance Imaging: Data Acquisition and Analysis","level":"G","description":"Provides background necessary for designing, conducting, and interpreting fMRI studies in the human brain. Covers in depth the physics of image encoding, mechanisms of anatomical and functional contrasts, the physiological basis of fMRI signals, cerebral hemodynamics, and neurovascular coupling. Also covers design methods for stimulus-, task-driven and resting-state experiments, as well as workflows for model-based and data-driven analysis methods for data. Instruction in brain structure analysis and surface- and region-based analyses. Laboratory sessions include data acquisition sessions at the 3 Tesla MRI scanner at MIT and the Connectom and 7 Tesla scanners at the MGH/HST Martinos Center, as well as hands-on data analysis workshops. Introductory or college-level neurobiology, physics, and signal processing are helpful.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:00","end":"16:00","room":"4-231"}]},{"type":"Lab","options":[{"days":["M"],"start":"12:30","end":"14:00","room":"4-149"}]},{"type":"Recitation","options":[{"days":["W"],"start":"14:00","end":"15:00","room":"4-231"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.583"},{"code":"HST.590","title":"Biomedical Engineering Seminar Series","level":"G","description":"Seminars focused on the development of professional skills for biomedical engineers and scientists. Each term focuses on a different topic, resulting in a repeating cycle that covers biomedical and research ethics, business and entrepreneurship, global health and biomedical innovation, and health systems and policy. Includes guest lectures, case studies, interactive small group discussions, and role-playing simulations.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"16:30","end":"18:30","room":"E25-117"}]}],"url":"http://student.mit.edu/catalog/mHSTa.html#HST.590"},{"code":"HST.920","title":"Principles and Practice of Drug Development","level":"G","description":"Description and critical assessment of the major issues and stages of developing a pharmaceutical or biopharmaceutical. Drug discovery, preclinical development, clinical investigation, manufacturing and regulatory issues considered for small and large molecules. Economic and financial considerations of the drug development process. Multidisciplinary perspective from faculty in clinical; life; and management sciences; as well as industry guests.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"18:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/mHSTb.html#HST.920"},{"code":"HST.974","title":"Innovating for Mission Impact in Medicine and Healthcare","level":"G","description":"Through a mentored experience, and in conjunction with the MIT Catalyst program, participants develop and validate a small portfolio of research opportunities/proposals. Provides experience with critical professional skills (interfacing with diverse experts, research strategy, critically evaluating the landscape and potential to add value, proposal development, communication, etc.) that heightens the potential to have meaningful impact through their work and career. Restricted to MIT Catalyst Fellows.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"10:00","end":"13:00","room":"E25-406"}]}],"url":"http://student.mit.edu/catalog/mHSTb.html#HST.974"},{"code":"IDS.014","title":"Fundamentals of Statistics","level":"U","description":"A rapid introduction to the theoretical foundations of statistical methods that are useful in many applications. Covers a broad range of topics in a short amount of time with the goal of providing a rigorous and cohesive understanding of the modern statistical landscape. Mathematical language is used for intuition and basic derivations but not proofs. Main topics include: parametric estimation, confidence intervals, hypothesis testing, Bayesian inference, and linear and logistic regression. Additional topics may include: causal inference, nonparametric estimation, and classification.","groups":[{"type":"Lecture","options":[{"days":["M","W","F"],"start":"10:00","end":"11:00","room":"2-190"}]},{"type":"Recitation","options":[{"days":["R"],"start":"11:00","end":"12:00","room":"4-149"},{"days":["R"],"start":"12:00","end":"13:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.014"},{"code":"IDS.045","title":"System Safety","level":"U","description":"Introduces the concepts of system safety and how to analyze and design safer systems. Topics include the causes of accidents in general, and recent major accidents in particular; hazard analysis, safety-driven design techniques; design of human-automation interaction; integrating safety into the system engineering process; and managing and operating safety-critical systems.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.045"},{"code":"IDS.063","title":"People and the Planet: Environmental Governance and Science","level":"U","description":"Introduces governance and science aspects of complex environmental problems and approaches to solutions. Introduces quantitative analyses and methodological tools to analyze environmental issues that have human and natural components. Demonstrates concepts through a series of in-depth case studies of environmental governance and science problems. Students develop writing, quantitative modeling, and analytical skills in assessing environmental systems problems and developing solutions. Through experiential activities, such as modeling and policy exercises, students engage with the challenges and possibilities of governance in complex, interacting systems, including biogeophysical processes and societal and stakeholder interactions.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"09:30","end":"12:30","room":"54-820"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.063"},{"code":"IDS.066","title":"Law, Technology, and Public Policy","level":"U","description":"Examines how law, economics, and technological change shape public policy, and how law can sway technological change; how the legal system responds to environmental, safety, energy, social, and ethical problems; how law and markets interact to influence technological development; and how law can affect wealth distribution, employment, and social justice. Covers energy/climate change; genetic engineering; telecommunications and role of misinformation; industrial automation; effect of regulation on technological innovation; impacts of antitrust law on innovation and equity; pharmaceuticals; nanotechnology; cost/benefit analysis as a decision tool; public participation in governmental decisions affecting science and technology; corporate influence on technology and welfare; and law and economics as competing paradigms to encourage sustainability. Students taking graduate version explore subject in greater depth.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.066"},{"code":"IDS.140","title":"Reinforcement Learning: Foundations and Methods","level":"G","description":"Examines reinforcement learning (RL) as a methodology for approximately solving sequential decision-making under uncertainty, with foundations in optimal control and machine learning. Provides a mathematical introduction to RL, including dynamic programming, statistical, and empirical perspectives, and special topics. Core topics include: dynamic programming, special structures, finite and infinite horizon Markov Decision Processes, value and policy iteration, Monte Carlo methods, temporal differences, Q-learning, stochastic approximation, and bandits. Also covers approximate dynamic programming, including value-based methods and policy space methods. Applications and examples drawn from diverse domains. Focus is mathematical, but is supplemented with computational exercises. An analysis prerequisite is suggested but not required; mathematical maturity is necessary.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"34-101"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"26-210"},{"days":["F"],"start":"11:00","end":"12:00","room":"26-142"},{"days":["F"],"start":"13:00","end":"14:00","room":"26-314"},{"days":["F"],"start":"14:00","end":"15:00","room":"26-314"},{"days":["F"],"start":"15:00","end":"16:00","room":"26-314"},{"days":["F"],"start":"16:00","end":"17:00","room":"56-154"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.140"},{"code":"IDS.190","title":"Doctoral Seminar in Statistics and Data Science","level":"G","description":"Interdisciplinary seminar explores diverse topics in statistics and data science. Restricted to students in the Interdisciplinary Doctoral Program in Statistics.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"11:00","end":"12:00","room":"E18-304"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.190"},{"code":"IDS.332","title":"System Design and Management for a Changing World: Combined","level":"G","description":"Practical-oriented subject that builds upon theory and methods and culminates in extended application. Covers methods to identify, value, and implement flexibility in design (real options). Topics include definition of uncertainties, simulation of performance for scenarios, screening models to identify desirable flexibility, decision analysis, and multidimensional economic evaluation. Students demonstrate proficiency through an extended application to a system design of their choice. Complements research or thesis projects. Class is 'flipped' to maximize student engagement and learning. Meets with IDS.333 in the first half of term. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.332"},{"code":"IDS.333","title":"System Design and Management for a Changing World: Tools","level":"G","description":"Focuses on design choices and decisions under uncertainty. Topics include identification and description of uncertainties using probability distributions; the calculation of commensurate measures of value, such as expected net present values; Monte Carlo simulation and risk analysis; and the use of decision analysis to explore alternative strategies and identify optimal initial choices. Presents applied analysis of practical examples from a variety of engineering systems using spreadsheet and decision analysis software. Class is 'flipped' to maximize student engagement and learning. Meets with IDS.332 first half of term.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.333"},{"code":"IDS.334","title":"System Design and Management for a Changing World: Projects","level":"G","description":"Focuses on implementation of flexibility (real options) in the design of products, start-ups, ongoing management of operations, or policy plans. Applies the methods presented in IDS.333: recognition of uncertainty, identification of best opportunities for flexibility, and valuation of these options and their effective implementation. Students work on their own project concept, for which they develop a dynamic business plan for design, deployment, and most beneficial implementation of their system over time. Useful complement to thesis or research projects. Class is 'flipped' to maximize student engagement and learning. Subject meets in second half of term in the fall and first half of term in the spring.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.334"},{"code":"IDS.340","title":"System Safety Concepts","level":"G","description":"Covers important concepts and techniques in designing and operating safety-critical systems. Topics include the nature of risk, formal accident and human error models, causes of accidents, fundamental concepts of system safety engineering, system and software hazard analysis, designing for safety, fault tolerance, safety issues in the design of human-machine interaction, verification of safety, creating a safety culture, and management of safety-critical projects. Includes a class project involving the high-level system design and analysis of a safety-critical system. Enrollment may be limited.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"12:00","room":"32-141"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.340"},{"code":"IDS.344","title":"Applied Category Theory for Engineering Design","level":"G","description":"Considers the multiple trade-offs at various abstraction levels and scales when designing complex, multi-component systems. Covers topics from foundational principles to advanced applications, emphasizing the role of compositional thinking in engineering. Introduces category theory as a mathematical framework for abstraction and composition, enabling a unified and modular approach to modeling, analyzing, and designing interconnected systems. Showcases successful applications in areas such as dynamical systems and automated system design optimization, with a focus on autonomous robotics and mobility. Offers students the opportunity to work on their own application through a dedicated project in the second half of the term. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"5-234"}]},{"type":"Recitation","options":[{"days":["F"],"start":"13:00","end":"14:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.344"},{"code":"IDS.405","title":"Critical Internet Studies","level":"G","description":"Focuses on the power dynamics in internet-related technologies (including social networking platforms, surveillance technology, entertainment technologies, and emerging media forms). Theories and readings focus on the cultural, social, economic, and political aspects of internet use and design, with a special attention to gender and race. Topics include: online communication and communities, algorithms and search engines, activism and online resistance, surveillance and privacy, content moderation and platform governance, and the spread of dis- and misinformation. Instruction and practice in written and oral communication provided. Students taking the graduate version complete additional readings and assignments.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"66-154"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.405"},{"code":"IDS.411","title":"Concepts and Research in Technology and Policy","level":"G","description":"Core integrative subject, with substantive participation from a series of guest faculty lecturers, examines key technology-policy concepts. Explores alternative framings of roles of technology in policy, emphasizing the implications of these alternatives upon problem-solving in the area. Exercises prepare students to apply these concepts in the framing of their thesis research. Preference to first-year students in the Technology and Policy Program.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"32-155"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.411"},{"code":"IDS.412","title":"Science, Technology, and Public Policy","level":"G","description":"Analysis of issues at the intersection of science, technology, public policy, and business. Cases drawn from antitrust and intellectual property rights; health and environmental policy; defense procurement and strategy; strategic trade and industrial policy; and R&D funding. Structured around theories of political economy, modified to take account of integration of uncertain technical information into public and private decision-making. Meets with 17.309 when offered concurrently.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.412"},{"code":"IDS.435","title":"Law, Technology, and Public Policy","level":"G","description":"Examines how law, economics, and technological change shape public policy, and how law can sway technological change; how the legal system responds to environmental, safety, energy, social, and ethical problems; how law and markets interact to influence technological development; and how law can affect wealth distribution, employment, and social justice. Covers energy/climate change; genetic engineering; telecommunications and the role of misinformation; industrial automation; effect of regulation on technological innovation; impacts of antitrust law on innovation and equity; pharmaceuticals; nanotechnology; cost/benefit analysis as a decision tool; public participation in governmental decisions affecting science and technology; corporate influence on technology and welfare; and law and economics as competing paradigms to encourage sustainability. Students taking graduate version explore subject in greater depth.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"E51-057"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.435"},{"code":"IDS.437","title":"Technology, Globalization, and Sustainable Development","level":"G","description":"Investigates sustainable development, taking a broad view to include not only a healthy economic base, but also a sound environment, stable and rewarding employment, adequate purchasing power and earning capacity, distributional equity, national self-reliance, and maintenance of cultural integrity. Explores national, multinational, and international political and legal mechanisms to further sustainable development through transformation of the industrial state. Addresses the importance of technological innovation and the financial crisis of 2008 and the emergence of the Covid-19 pandemic, Russia's invasion of Ukraine, and inflation, as well as governmental interventions to reduce inequality.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"16:00","end":"18:30","room":"E51-376"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.437"},{"code":"IDS.449","title":"Technology Policy Internship and Professional Perspectives Seminar","level":"G","description":"Seminar examines what technology policy is in practice. Considers the question of 'Who achieves what, when, how, and why?' regarding technology and policy. Students who completed summer internships present and dissect their experiences with special reference to specific cases in which they participated. Develops perspectives on practice in the field through sessions with alumni, other practitioners, and development professionals within MIT.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"12:00","end":"14:00","room":"E18-304"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.449"},{"code":"IDS.620","title":"Principles and Practice of Drug Development","level":"G","description":"Description and critical assessment of the major issues and stages of developing a pharmaceutical or biopharmaceutical. Drug discovery, preclinical development, clinical investigation, manufacturing and regulatory issues considered for small and large molecules. Economic and financial considerations of the drug development process. Multidisciplinary perspective from faculty in clinical; life; and management sciences; as well as industry guests.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"15:00","end":"18:00","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.620"},{"code":"IDS.730","title":"Logistics Systems","level":"G","description":"Provides an introduction to supply chain management from both analytical and practical perspectives. Taking a unified approach, students develop a framework for making intelligent decisions within the supply chain. Covers key logistics functions, such as demand planning, procurement, inventory theory and control, transportation planning and execution, reverse logistics, and flexible contracting. Explores concepts such as postponement, portfolio management, and dual sourcing. Emphasizes skills necessary to recognize and manage risk, analyze various tradeoffs, and model logistics systems. SCM.271 meets with SCM.260, but has fewer assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.730"},{"code":"IDS.865","title":"Foundations of AI Ventures","level":"G","description":"Seminar focuses on developing and building entrepreneurial ventures to drive global positive impact. Students tackle challenges in the broad sectors of digital health, sustainability, fintech, and the decentralization of society and commerce by developing enduring and economically viable solutions. Topics include blockchain, privacy-tech, data markets, and AI technologies such as Web3 and Distributed Machine Learning. Guest speakers and case studies reveal successes and failures in deploying products and services. Homework explores established and emerging business models, plus opportunities from innovations at MIT and beyond. The final project involves creating an executive summary for a business plan, suitable for submission to the MIT $100K Entrepreneurship Competition's Accelerate Contest or MIT IDEAS. Enrollment is limited; please see subject website for details.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:00","end":"12:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.865"},{"code":"IDS.900","title":"Doctoral Seminar in Social and Engineering Systems","level":"G","description":"Introduces doctoral students to IDSS research areas. Preference to first-year students in SES.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"09:00","end":"10:30","room":"E18-411"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.900"},{"code":"IDS.C57","title":"Optimization Methods","level":"G","description":"Introduction to the methods and applications of optimization. Topics include linear optimization, duality, non-linear optimization, integer optimization, and optimization under uncertainty. Instruction provided in modeling techniques to address problems arising in practice, mathematical theory to understand the structure of optimization problems, computational algorithms to solve complex optimization problems, and practical applications. Covers several examples and in-depth case studies based on real-world data to showcase impactful applications of optimization across management and engineering. Computational exercises based on the Julia-based programming language JuMP. Includes a term project. Basic competency in computational programming and linear algebra recommended. Students taking graduate version complete additional assignments. This subject was previously listed as 15.093/6.7200/IDS.200. One section primarily reserved for Sloan students; check syllabus for details.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-345"},{"days":["T","R"],"start":"14:30","end":"16:00","room":"E25-111"},{"days":["M","W"],"start":"10:00","end":"11:30","room":"E25-111"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:00","room":"E51-345"},{"days":["F"],"start":"13:00","end":"14:00","room":"45-230"},{"days":["F"],"start":"14:00","end":"15:00","room":"45-230"}]}],"url":"http://student.mit.edu/catalog/mIDSa.html#IDS.C57"},{"code":"MAD.501","title":"MAD Fellows Seminar I","level":"G","description":"Explores design methodologies in graduate research as well as contemporary issues in design practices. Guest lecturers present themes of common interest and share sources of design inspiration. Limited to graduate student fellows supported by the Morningside Academy for Design.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"11:00","end":"13:00","room":"W41-1401"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.501"},{"code":"MAD.701","title":"D-Lab: Development","level":"U","description":"Issues in international development, appropriate technology and project implementation addressed through lectures, case studies, guest speakers and laboratory exercises. Students form project teams to partner with community organizations in developing countries, and formulate plans for an optional IAP site visit. (Previous field sites include Ghana, Brazil, Honduras and India.) Recitation sections focus on specific project implementation, and include cultural, social, political, environmental and economic overviews of the target countries as well as an introduction to the local languages. Enrollment limited by lottery; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["F"],"start":"15:30","end":"17:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.701"},{"code":"MAD.712","title":"Applications of Energy in Global Development","level":"U","description":"Engages students in project-based learning, in collaboration with D-Lab community partners, to improve access to affordable, reliable, sustainable, and modern energy for all. Teams work on off-grid energy projects addressing challenges in lighting, cooking, agricultural productivity, or other areas in collaboration with D-Lab community partners in developing countries. Project work includes assessment of user needs, technology identification, product design, prototyping, and development of implementation strategies to continue progress of ongoing projects. Optional IAP field visits may be available to test and implement the solutions developed during the semester. Students enrolled in the graduate version complete additional assignments.  Limited to 20; preference to students who have taken EC.711.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"15:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.712"},{"code":"MAD.729","title":"D-Lab: Design for Scale","level":"U","description":"Explores the external factors affecting product development for people in low-resource settings in a project-based context. Students apply existing engineering skills in interdisciplinary teams to identify contextual limitations and develop previously established prototypes towards manufacturing-ready product designs for real-world project sponsors. Topics are presented within the context of the developing world and include technology feasibility and scalability assessment; value chain analysis; product specification; and manufacturing methodologies at various scales. Lessons are experiential and case study-based, taught by instructors with field experience and industry experts from product development consulting firms and the consumer electronics industry. Students taking graduate version complete additional written assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["R"],"start":"14:00","end":"15:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.729"},{"code":"MAD.750","title":"Humanitarian Innovation: Design for Relief, Rebuilding, and Recovery","level":"U","description":"Explores the role innovation can and does play in how humanitarian aid is provided, and how it can impact people, products, and processes. Provides a fundamental background in the history and practice of humanitarian aid. Considers the various ways that design can be used to enhance aid, such as product and system design for affected populations, co-creation with affected populations, and capacity building to promote design by refugees and the displaced. Case studies and projects examine protracted displacement as well as recovery and resettlement, including efforts in Colombia, Lebanon, Nepal, Sudan, and Uganda. Potential for students to travel over the summer to partner communities.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"15:00","room":"N51-350"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.750"},{"code":"MAD.768","title":"D-Lab: Gender and Development","level":"U","description":"Explores gender roles, illuminates the power dynamics and root causes of inequality, and provides a framework for understanding gender dynamics. Develops skills to conduct a gender analysis and integrate gender-sensitive strategies into large- and small-scale development solutions. Prompts critical discussion about social, economic, and political conditions that shape gender in development. Begins with exploration of international development in the post-colonial era, using a gender lens, then provides students with the tools to integrate gender-sensitive strategies into international development work, with a particular focus on launching, building and scaling women's ventures. Opportunities may be available for international fieldwork over IAP. Meets with 24.234 when offered concurrently. Students taking graduate version complete additional assignments. Limited to 12; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.768"},{"code":"MAD.781","title":"D-Lab: Development","level":"G","description":"Issues in international development, appropriate technology and project implementation addressed through lectures, case studies, guest speakers and laboratory exercises. Students form project teams to partner with community organizations in developing countries, and formulate plans for an optional IAP site visit. (Previous field sites include Ghana, Brazil, Honduras and India.) Recitation sections focus on specific project implementation, and include cultural, social, political, environmental and economic overviews of the target countries as well as an introduction to the local languages. Enrollment limited by lottery; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["F"],"start":"15:30","end":"17:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.781"},{"code":"MAD.785","title":"Humanitarian Innovation: Design for Relief, Rebuilding, and Recovery","level":"G","description":"Explores the role innovation can and does play in how humanitarian aid is provided, and how it can impact people, products, and processes. Provides a fundamental background in the history and practice of humanitarian aid. Considers the various ways that design can be used to enhance aid, such as product and system design for affected populations, co-creation with affected populations, and capacity building to promote design by refugees and the displaced. Case studies and projects examine protracted displacement as well as recovery and resettlement, including efforts in Colombia, Lebanon, Nepal, Sudan, and Uganda. Potential for students to travel over the summer to partner communities.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"15:00","room":"N51-350"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.785"},{"code":"MAD.792","title":"Applications of Energy in Global Development","level":"G","description":"Engages students in project-based learning in collaboration with D-Lab community partners to improve access to affordable, reliable, sustainable, and modern energy for all. Teams work on off-grid energy projects addressing challenges in lighting, cooking, agricultural productivity, or other areas in collaboration with D-Lab community partners in developing countries. Project work includes assessment of user needs, technology identification, product design, prototyping, and development of implementation strategies to continue progress of ongoing projects. Optional IAP field visits may be available to test and implement the solutions developed during the semester. Students enrolled in the graduate version complete additional assignments.  Limited to 20; preference to students who have taken EC.791.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"15:00","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.792"},{"code":"MAD.798","title":"D-Lab: Gender and Development","level":"G","description":"Explores gender roles, illuminates the power dynamics and root causes of inequality, and provides a framework for understanding gender dynamics. Develops skills to conduct a gender analysis and integrate gender-sensitive strategies into large- and small-scale development solutions. Prompts critical discussion about social, economic, and political conditions that shape gender in development. Begins with exploration of international development in the post-colonial era, using a gender lens, then provides students with the tools to integrate gender-sensitive strategies into international development work, with a particular focus on launching, building and scaling women's ventures. Opportunities may be available for international fieldwork over IAP. Meets with 24.634 when offered concurrently. Students taking graduate version complete additional assignments. Limited to 12; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.798"},{"code":"MAD.799","title":"D-Lab: Design for Scale","level":"G","description":"Explores the external factors affecting product development for people in low-resource settings in a project-based context. Students apply existing engineering skills in interdisciplinary teams to identify contextual limitations and develop previously established prototypes towards manufacturing-ready product designs for real-world project sponsors. Topics are presented within the context of the developing world and include technology feasibility and scalability assessment; value chain analysis; product specification; and manufacturing methodologies at various scales. Lessons are experiential and case study-based, taught by instructors with field experience and industry experts from product development consulting firms and the consumer electronics industry. Students taking graduate version complete additional written assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"N51-310"}]},{"type":"Lab","options":[{"days":["R"],"start":"14:00","end":"15:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.799"},{"code":"MAD.802","title":"Entrepreneurship in the Built Environment","level":"G","description":"Introduction to entrepreneurship and how it shapes the world we live in. Through experiential learning in a workshop setting, students start to develop entrepreneurial mindset and skills. Through a series of workshops, students are introduced to the concept of Venture Design to create new venture proposals for the built environment as a method to understand the role of the entrepreneur in the fields of design, planning, real estate, and other related industries.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:00","end":"11:00","room":"W41-1401"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.802"},{"code":"MAD.804","title":"Systems Change for Social Impact","level":"G","description":"Explores the difference between innovation, social innovation, and systems change for social impact. Presents frameworks and case studies from real systems change innovators to develop a more comprehensive view of complex problems and the systems they are part of ? systems that often keep those problems in place. Using experiential tools, students explore problem framing from the impact target's perspective and innovative, scalable approaches to systems change. Final deliverable is a written case study on systems change based on detailed actor mapping and interviews where students share their deeper understanding of a system they care about.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:00","end":"11:00","room":"W41-1401"}]}],"url":"http://student.mit.edu/catalog/mMADa.html#MAD.804"},{"code":"MAS.552","title":"City Science","level":"G","description":"Focuses on innovative propositions for shaping the cities of tomorrow, responding to emerging trends, technologies, and ecological imperatives. Students take part in 'what-if?' scenarios to tackle real-world challenges. Through collaborative, project-based learning in small teams, students are mentored by researchers from the City Science group. Projects focus on the application of these ideas to case study cities and may include travel. Invited guests from academia and industry participate. Repeatable for credit with permission of instructor.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"E15-341"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.552"},{"code":"MAS.665","title":"Foundations of AI Ventures","level":"G","description":"Seminar focuses on developing and building entrepreneurial ventures to drive global positive impact. Students tackle challenges in the broad sectors of digital health, sustainability, fintech, and the decentralization of society and commerce by developing enduring and economically viable solutions. Topics include blockchain, privacy-tech, data markets, and AI technologies such as Web3 and Distributed Machine Learning. Guest speakers and case studies reveal successes and failures in deploying products and services. Homework explores established and emerging business models, plus opportunities from innovations at MIT and beyond. The final project involves creating an executive summary for a business plan, suitable for submission to the MIT $100K Entrepreneurship Competition's Accelerate Contest or MIT IDEAS. Enrollment is limited; please see subject website for details.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:00","end":"12:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.665"},{"code":"MAS.834","title":"Tangible Interfaces","level":"G","description":"Explores design issues surrounding tangible user interfaces, a new form of human-computer interaction. Tangible user interfaces seek to realize seamless interfaces between humans, digital information, and the physical environment by giving physical form to digital information and computation, making bits directly manipulable with hands and perceptible at the periphery of human awareness. In the design studio environment, students explore experimental tangible interface designs, theories, applications, and underlying technologies, using concept sketches, posters, physical mockups, and working prototypes.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"13:00","end":"16:00","room":"E15-341"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.834"},{"code":"MAS.838","title":"Prototyping our Sci-Fi Space Future: Designing & Deploying Projects for Zero Gravity Flights","level":"G","description":"Instruction in project development, prototyping, and deployment readiness for parabolic flights. Admitted student teams are offered flyer and project-deployment slots on the Space Exploration Initiative's spring parabolic flight, upon successful completion of the course in the fall and integration with the flight provider. Covers three main topic areas: 1) rapid prototyping and engineering skills to prepare projects for operation in microgravity; 2) logistics, training, and safety pre-approval steps to meet flight readiness requirements and pass a Technical Readiness Review (TRR); and 3) creative and technical lenses for the future of space exploration, examining the MIT Space Exploration Initiative's design and prototyping approach, and MIT parabolic flight research examples across Science, Engineering, Art, and Design, and across departments. Enrollment limited; admission by application.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"33-218"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.838"},{"code":"MAS.858","title":"Asking How Space Enabled Designs Advance Justice and Development","level":"G","description":"Examines theoretical and practical challenges of applying complex technology, such as space systems, to advance justice and development within human society. Proposes and critiques a concept of justice and development based on attainment of the US Sustainable Development Goals. Analyzes text by historians and economists around global patterns of uneven technology access. Teaches systems engineering tools to analyze the context, stakeholders, functions and forms of complex systems that impact society. Presents six space technologies used for specific Sustainable Development Goal. Students read several text, discuss key themes, write reflective responses, and write a research proposal on a topic of their choice. Part of two-class series on space technology and sustainable development. Limited to 15.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"09:00","end":"12:00","room":"E14-493"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.858"},{"code":"MAS.863","title":"How to Make (Almost) Anything","level":"G","description":"Provides a practical hands-on introduction to digital fabrication, including CAD/CAM/CAE, NC machining, 3-D printing and scanning, molding and casting, composites, laser and waterjet cutting, PCB design and fabrication; sensors and actuators; mixed-signal instrumentation, embedded processing, and wired and wireless communications. Develops an understanding of these capabilities through projects using them individually and jointly to create functional systems.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"E14-633"}]},{"type":"Recitation","options":[{"days":["R"],"start":"17:00","end":"19:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.863"},{"code":"MAS.881","title":"Principles of Neuroengineering","level":"G","description":"Covers how to innovate technologies for brain analysis and engineering, for accelerating the basic understanding of the brain, and leading to new therapeutic insight and inventions. Focuses on using physical, chemical and biological principles to understand technology design criteria governing ability to observe and alter brain structure and function. Topics include optogenetics, noninvasive brain imaging and stimulation, nanotechnologies, stem cells and tissue engineering, and advanced molecular and structural imaging technologies. Includes design projects. Designed for students with engineering maturity who are ready for design. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"46-5165"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.881"},{"code":"MAS.883","title":"Revolutionary Ventures: How to Invent and Deploy Transformative Technologies","level":"G","description":"Seminar on envisioning and building ideas and organizations to accelerate engineering revolutions. Focuses on emerging technology domains, such as neurotechnology, imaging, cryotechnology, gerontechnology, and bio-and-nano fabrication. Draws on historical examples as well as live case studies of existing or emerging organizations, including labs, institutes, startups, and companies. Goals range from accelerating basic science to developing transformative products or therapeutics. Each class is devoted to a specific area, often with invited speakers, exploring issues from the deeply technical through the strategic. Individually or in small groups, students prototype new ventures aimed at inventing and deploying revolutionary technologies.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:00","end":"16:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.883"},{"code":"MAS.921","title":"Proseminar in Media Arts and Sciences","level":"G","description":"Designed specifically for new doctoral students in the Media Arts and Sciences (MAS) program. Explores intellectual foundations of MAS, unifying themes connecting MAS research, and working practices of MAS researchers. Restricted to MAS doctoral students.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"13:00","end":"15:00","room":"E15-341"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.921"},{"code":"MAS.941","title":"Preparation for SM Thesis II","level":"G","description":"Guides students in the selection of thesis topic, definition of method of approach, and preparation for Crit Day and thesis proposal.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"10:00","end":"12:00","room":"E14-633"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.941"},{"code":"MAS.S60","title":"Special Subject in Media Technology","level":"G","description":"Supplementary work in areas not covered by the regular curriculum. Registration subject to prior arrangement.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"11:00","end":"13:00","room":"E15-341"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.S60-MAS.S64"},{"code":"MAS.S61","title":"Special Subject in Media Technology","level":"G","description":"Supplementary work in areas not covered by the regular curriculum. Registration subject to prior arrangement.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"16:00","end":"18:00","room":"E15-359"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.S60-MAS.S64"},{"code":"MAS.S62","title":"Special Subject in Media Technology","level":"G","description":"Supplementary work in areas not covered by the regular curriculum. Registration subject to prior arrangement.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"14:00","end":"16:00","room":"E15-359"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.S60-MAS.S64"},{"code":"MAS.S63","title":"Special Subject in Media Technology","level":"G","description":"Supplementary work in areas not covered by the regular curriculum. Registration subject to prior arrangement.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"14:00","end":"17:00","room":"E15-341"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.S60-MAS.S64"},{"code":"MAS.S64","title":"Special Subject in Media Technology","level":"G","description":"Supplementary work in areas not covered by the regular curriculum. Registration subject to prior arrangement.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"E15-341"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.S60-MAS.S64"},{"code":"MAS.S65","title":"Special Subject in Media Technology","level":"G","description":"Supplementary work in areas not covered by the regular curriculum. Registration subject to prior arrangement.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:30","end":"16:00","room":"E15-359"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.S65-MAS.S69"},{"code":"MAS.S70","title":"Special Subject in Media Technology","level":"G","description":"Supplementary work in areas not covered by the regular curriculum.  Registration subject to prior arrangement.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"13:00","end":"15:00","room":"E15-359"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.S70"},{"code":"MAS.S90","title":"Special Subject in Media Arts and Sciences","level":"G","description":"Supplementary work in areas not covered by the regular curriculum. Registration subject to prior arrangement.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"15:00","end":"17:00","room":"E15-341"}]}],"url":"http://student.mit.edu/catalog/mMASa.html#MAS.S90"},{"code":"SCM.251","title":"Supply Chain Financial Analysis","level":"G","description":"Explores the linkages between supply chain management and corporate finance. Emphasizes how the supply chain creates value for both the shareholders of the company and for the stakeholders affected by the company's operations. Sessions combine lectures and data-rich cases from the manufacturer, distributor, and retailer perspective. Topics include accounting fundamentals, financial analysis, activity-based costing, working capital management, cash flow projections, capital budgeting, and sustainability.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"E51-149"}]},{"type":"Recitation","options":[{"days":["F"],"start":"10:00","end":"11:30","room":"E52-164"}]}],"url":"http://student.mit.edu/catalog/mSCMa.html#SCM.251"},{"code":"SCM.260","title":"Logistics Systems","level":"G","description":"Provides an introduction to supply chain management from both analytical and practical perspectives. Taking a unified approach, students develop a framework for making intelligent decisions within the supply chain. Covers key logistics functions, such as demand planning, procurement, inventory theory and control, transportation planning and execution, reverse logistics, and flexible contracting. Explores concepts such as postponement, portfolio management, and dual sourcing. Emphasizes skills necessary to recognize and manage risk, analyze various tradeoffs, and model logistics systems. SCM.271 meets with SCM.260, but has fewer assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/mSCMa.html#SCM.260"},{"code":"SCM.264","title":"Databases and Data Analysis for Supply Chain Management","level":"G","description":"Introduces databases, data analysis, and machine learning topics. Covers data modeling, relational databases, SQL queries, data mining, non-relational databases, and data warehouses. Introduces data analysis tools for visualization, regression, supervised and unsupervised techniques including principal component analysis and clustering. Term project includes implementation of data model, database, visualization and data analysis. SCM.274 meets with SCM.264 but requires fewer assignments and lectures. Restricted to SCM students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E25-111"}]},{"type":"Lab","options":[{"days":["W"],"start":"16:00","end":"17:30","room":"E51-372"}]}],"url":"http://student.mit.edu/catalog/mSCMa.html#SCM.264"},{"code":"SCM.271","title":"Logistics Systems Topics","level":"G","description":"Provides an introduction to supply chain management from both analytical and practical perspectives. Taking a unified approach, students develop a framework for making intelligent decisions within the supply chain. Covers key logistics functions, such as demand planning, procurement, inventory theory and control, transportation planning and execution, reverse logistics, and flexible contracting. Explores concepts such as postponement, portfolio management, and dual sourcing. Emphasizes skills necessary to recognize and manage risk, analyze various tradeoffs, and model logistics systems. SCM.271 meets with SCM.260, but has fewer assignments. Restricted to students who previously completed the edX course SC1x Supply Chain Fundamentals.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"08:30","end":"10:00","room":"E51-149"}]}],"url":"http://student.mit.edu/catalog/mSCMa.html#SCM.271"},{"code":"SCM.274","title":"Databases and Data Analysis Topics for Supply Chain Management","level":"G","description":"Introduces databases, data analysis, and machine learning topics. Covers data modeling, relational databases, SQL queries, data mining, non-relational databases, and data warehouses. Introduces data analysis tools for visualization, regression, supervised and unsupervised techniques including principal component analysis and clustering. Term project includes implementation of data model, database, visualization and data analysis. SCM.274 meets with SCM.264 but requires fewer assignments and lectures. Restricted to SCM students.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"E25-111"}]},{"type":"Lab","options":[{"days":["W"],"start":"16:00","end":"17:30","room":"E51-372"}]}],"url":"http://student.mit.edu/catalog/mSCMa.html#SCM.274"},{"code":"SCM.275","title":"Advanced Supply Chain Systems Planning and Network Design","level":"G","description":"Explores the challenges of supply chain design in the dynamic and uncertain context of the contemporary supply chains. Introduces students to the most common decisions in supply chain design, the main trade-offs associated with those decisions, and the fundamental quantitative methods for used in supply chain design. Helps students translate a real-life business decision-making problem into a formal supply chain network design mathematical model.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-149"}]},{"type":"Recitation","options":[{"days":["R"],"start":"13:00","end":"14:30","room":"E51-145"}]}],"url":"http://student.mit.edu/catalog/mSCMa.html#SCM.275"},{"code":"SP.248","title":"The NEET Experience","level":"U","description":"Gives first-year students an opportunity to explore various interdisciplinary domains, or threads — Autonomous Machines, Climate and Sustainability Systems, Digital Cities, and Living Machines — all of which are a part of the New Engineering Education Transformation (NEET) program. Students gain knowledge and skills in those domains through interactions with NEET faculty, instructors, and students and exercise their algorithmic, creative, and systems thinking through team-based challenges. Subject can count toward the 6-unit discovery-focused credit limit for first-year students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"14:00","end":"15:00","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/mSPa.html#SP.248"},{"code":"SP.251","title":"How to Change the World: Experiences from Social Entrepreneurs","level":"U","description":"Every week, students meet a new role model who demonstrates what it means to change the world through social entrepreneurship, technology, or policy. Each session covers an aspect of social entrepreneurship, from identifying opportunities for change to innovation within specific topic areas to impact investing. Through these speakers, students gain a greater understanding of how technology-based, impactful solutions can address global challenges. Students learn to identify and address social and environmental problems and understand the relevance of this work for their time at MIT. By the end of the term, students identify what problems are of personal interest, and are connected to resources to continue their journey of social impact during their time at MIT. Subject can count toward the 6-unit discovery-focused credit limit for first year-students. Limited to 25; preference to first-year students.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"15:00","end":"16:30","room":"2-146"}]}],"url":"http://student.mit.edu/catalog/mSPa.html#SP.251"},{"code":"STS.003","title":"Ancient Greeks to Modern Geeks: A History of Science","level":"U","description":"Covers the development of major fields in the physical and life sciences, from 18th-century Europe through 20th-century America. Examines ideas, institutions, and the social settings of the sciences, with emphasis on how cultural contexts influence scientific concepts and practices.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"14:00","end":"15:00","room":"56-114"}]},{"type":"Recitation","options":[{"days":["W"],"start":"15:00","end":"16:00","room":"56-167"},{"days":["W"],"start":"15:00","end":"16:00","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.003"},{"code":"STS.004","title":"Intersections: Science, Technology, and the World","level":"U","description":"Exposes students to multidisciplinary studies in Science, Technology, and Society (STS), using four case studies to illustrate a broad range of approaches to basic principles of STS studies. Case studies vary from year to year, but always include a current MIT event. Other topics are drawn from legal and political conflicts, and arts and communication media. Includes guest presenters, discussion groups, field activities, visual media, and a practicum style of learning. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"14:30","end":"16:00","room":"32-144"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.004"},{"code":"STS.012","title":"Science in Action: Technologies and Controversies in Everyday Life","level":"U","description":"Explores how science and technology impact everyday life, through the lens of current controversies and debates. Students examine the role of scientific research, the tensions between human and technological boundaries, and how politics and culture shape technological practice. Subject materials draw from humanities and social science scholarship, documentaries, and other multimedia to explore science's dynamic and contested relationship with social life and cultural ideas. Students work to develop critical perspectives on how scientific practice intersects with society.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.012"},{"code":"STS.031","title":"Environment and History","level":"U","description":"Focusing on the period from 1500 to the present, explores the influence of climate, topography, plants, animals, and microorganisms on human history and the reciprocal influence of people on the environment. Topics include the European encounter with the Americas, the impact of modern technology, and the current environmental crisis. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"E51-385"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.031"},{"code":"STS.039","title":"History of Native Science","level":"U","description":"Tracks the history of Indigenous knowledge and engagements with colonial US and settler science. Explores traditional ecological knowledge, naturalized knowledge systems, and decolonized research methods ? among other frameworks ? and how the field of Native science came to be. Introduces critical STS and Indigenous methods for translating and engaging Indigenous knowledge and history, and traces how science and indigineity have been entangled through colonial and decolonial practice. Presents how Native science has been a galvanizing force for international research and policy on everything from climate science to genetics.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"E51-393"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.039"},{"code":"STS.046","title":"The Science of Race, Sex, and Gender","level":"U","description":"Examines the role of science and medicine in the origins and evolution of the concepts of race, sex, and gender from the 17th century to the present. Focus on how biological, anthropological, and medical concepts intersect with social, cultural, and political ideas about racial, sexual, and gender difference in the US and globally. Approach is historical and comparative across disciplines emphasizing the different modes of explanation and use of evidence in each field.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"26-139"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.046"},{"code":"STS.059","title":"The Bioeconomy and Society","level":"U","description":"Characterizes and examines the transformation of the production of fuels, foods, materials, and medicines through sustainable processes based on bacteria, fungi, algae, and plants, to inaugurate a biologically-based economy, or 'bioeconomy.' Studies this developing bioeconomy and its antecedent political, technological, and cultural events, as well as its potential social impacts. Includes guest speakers from policy, industry, and academia. Discusses the scientific research which offers outside perspectives on opportunities and challenges that the bioeconomy presents. Students work in project-based teams throughout the term to analyze the historical and contemporary dimensions of one feature of the bioeconomy.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"2-139"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.059"},{"code":"STS.065","title":"The Anthropology of Sound","level":"U","description":"Examines the ways humans experience sound and how perceptions and technologies of sound emerge from cultural, economic, and historical worlds. Consider how the sound/noise/music boundaries have been imagined, created, and modeled across sociocultural and historical contexts. Learn how environmental, linguistic, and musical sounds are construed cross-culturally as well as the rise of telephony, architectural acoustics, sound recording, multi-channel and spatial mix performance, and the globalized travel of these technologies. Questions of sound ownership, property, authorship, remix, and copyright in the digital age are also addressed.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"13:00","end":"16:00","room":"4-149"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.065"},{"code":"STS.074","title":"Art, Craft, Science","level":"U","description":"Examines how people learn, practice, and evaluate traditional and contemporary craft techniques. Social science theories of design, embodiment, apprenticeship learning, skill, labor, expertise, and tacit knowledge are used to explore distinctions among art, craft, and science. Also discusses the commoditization of craft into market goods, collectible art, and tourism industries. Ethnographic and historical case studies include textiles, Shaker furniture, glassblowing, quilting, cheesemaking, industrial design, home and professional cooking, factory and laboratory work, CAD/CAM. Demonstrations, optional field trips, and/or hands-on craft projects may be included. Students taking graduate version complete additional assignments.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:00","end":"12:30","room":"4-265"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.074"},{"code":"STS.075","title":"Technology and Culture","level":"U","description":"Examines the intersections of technology, culture, and politics in a variety of social and historical settings ranging from 19th-century factories to 21st-century techno dance floors, from Victorian London to anything-goes Las Vegas. Discussions and readings organized around three questions: what cultural effects and risks follow from treating biology as technology; how computers have changed the way we think about ourselves and others; and how politics are built into our infrastructures. Explores the forces behind technological and cultural change; how technological and cultural artifacts are understood and used by different communities; and whether, in what ways, and for whom technology has produced a better world. Limited to 50.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"19:00","end":"21:00","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.075"},{"code":"STS.083","title":"Computers and Social Change","level":"U","description":"Provides instruction on how people have historically connected computers to ideas on social, economic, and political change and how these ideas have changed over time. Based on a series of case studies from different parts of the world. Explores topics such as how computers have intertwined with ideas on work, freedom, governance, and access to knowledge. Limited to 25.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"19:00","end":"22:00","room":"E51-361"}]}],"url":"http://student.mit.edu/catalog/mSTSa.html#STS.083"},{"code":"STS.260","title":"Introduction to Science, Technology, and Society","level":"G","description":"Intensive reading and analysis of major works in historical and social studies of science and technology. Introduction to current methodological approaches, centered around two primary questions: how have science and technology evolved as human activities, and what roles do they play in society? Preparation for graduate work in the field of science and technology studies and introduction to research resources and professional standards.","groups":[{"type":"Lecture","options":[{"days":["T"],"start":"09:30","end":"12:30","room":"E51-165"}]}],"url":"http://student.mit.edu/catalog/mSTSb.html#STS.260"},{"code":"STS.410","title":"Technology and Capital","level":"G","description":"Examines the mutual constitution of technology and capital. Draws on Marx, labor process theory, and science and technology studies to explore how capitalist social relations shape technological development and how technological systems in turn produce and reinforce particular forms of accumulation, control, and value extraction. Topics include machinery and the labor process, deskilling and automation, the politics of technological design, and resistance to technological change. Engages thinkers including Marx, Braverman, Noble, and Winner alongside perspectives from the global south.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"14:30","end":"17:30","room":"E51-165"}]}],"url":"http://student.mit.edu/catalog/mSTSb.html#STS.410"},{"code":"STS.422","title":"African Philosophies of Science, Technology, and Innovation","level":"G","description":"Team-taught subject exploring the paradox of a continent with abundant natural and human resources that continues to struggle with widespread poverty. Suggests that Africa's problem is a mindset rooted in legacies of slavery and colonialism and that Africa can only add value to its natural resources if it adds value to its people first. Posits the role of curriculum design in mindset re-engineering, training critical thinker-doers who run toward, not away from, problems to solve them. Constitutes a return to an African educational philosophy of learning science, technology, and innovation through doing. Weekly topics ? with assigned readings, lectures, and assignments ? focus on a range of makers, making, and makerspaces. Each reading underpins designing, preparing, or making a product or service so students translate coursework into practice.","groups":[{"type":"Lecture","options":[{"days":["R"],"start":"10:00","end":"13:00","room":"E51-165"}]}],"url":"http://student.mit.edu/catalog/mSTSb.html#STS.422"},{"code":"STS.457","title":"Legacies of Scientific Racism: Race, Science, and Technology Today","level":"G","description":"Examines how race is made, upheld, or challenged through contemporary technoscientific practices. Draws on readings from the social, humanistic, and biological sciences to understand how modern scientific racism works today and debate the potential for an anti-racist science of the future. Topics include biomedical experimentation; DNA forensics and law; genetic ancestry testing and identity; neuroscience and mental health; and algorithms, AI, and robots.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"10:00","end":"13:00","room":"E51-165"}]}],"url":"http://student.mit.edu/catalog/mSTSb.html#STS.457"},{"code":"STS.482","title":"Science, Technology, and Public Policy","level":"G","description":"Analysis of issues at the intersection of science, technology, public policy, and business. Cases drawn from antitrust and intellectual property rights; health and environmental policy; defense procurement and strategy; strategic trade and industrial policy; and R&D funding. Structured around theories of political economy, modified to take account of integration of uncertain technical information into public and private decision-making. Meets with 17.309 when offered concurrently.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"66-168"}]}],"url":"http://student.mit.edu/catalog/mSTSb.html#STS.482"},{"code":"SWE.010","title":"","level":"G","description":"Practical-oriented subject that builds upon theory and methods and culminates in extended application. Covers methods to identify, value, and implement flexibility in design (real options). Topics include definition of uncertainties, simulation of performance for scenarios, screening models to identify desirable flexibility, decision analysis, and multidimensional economic evaluation. Students demonstrate proficiency through an extended application to a system design of their choice. Complements research or thesis projects. Class is 'flipped' to maximize student engagement and learning. Meets with IDS.333 in the first half of term. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"1-390"}]}],"url":"http://student.mit.edu/catalog/mSWEa.html#SWE.010"},{"code":"SWE.011","title":"","level":"U","description":"Explores how to be an ethical engineer. Students examine engineering case studies alongside key readings by foundational ethical thinkers from Aristotle to Martin Luther King, Jr., and investigate which ethical approaches are best and how to apply them. Topics include justice, rights, cost-benefit analysis, safety, bias, genetic engineering, climate change, and the promise and peril of AI. Discussion-based, with the aim of introducing students to new ways of thinking. All sections cover the same core ethical frameworks, but some sections have a particular focus for case studies, such as bioengineering, or have an in-depth emphasis on particular thinkers. The subject is taught in separate sections. Students are eligible to take any section regardless of their registered subject number. For 20.005, students additionally undertake an ethical-technical analysis of a BE-related topic of their choosing.","groups":[{"type":"Lecture","options":[{"days":["M"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["T"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"15:00","end":"17:00","room":"66-148"},{"days":["W"],"start":"19:00","end":"21:00","room":"66-148"},{"days":["R"],"start":"15:00","end":"17:00","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/mSWEa.html#SWE.011"},{"code":"SWE.015","title":"","level":"U","description":"Introduction and overview of engineering management. Financial principles, management of innovation, technical strategy and best management practices. Case study method of instruction emphasizes participation in class discussion. Focus is on the development of individual skills and management tools. Restricted to juniors and seniors.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"11:00","end":"12:30","room":"35-225"}]},{"type":"Lab","options":[{"days":["M"],"start":"16:00","end":"17:00","room":"1-150"},{"days":["T"],"start":"10:00","end":"11:00","room":"1-375"},{"days":["R"],"start":"16:00","end":"17:00","room":"1-375"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-135"}]}],"url":"http://student.mit.edu/catalog/mSWEa.html#SWE.015"},{"code":"SWE.017","title":"","level":"U","description":"Provides students with skills to prepare for and excel in the world of industry. Emphasizes practical application of career theory and professional development concepts. Introduces students to relevant and timely resources for career development, provides students with tools to embark on a successful internship search, and offers networking opportunities with employers and MIT alumni. Students work in groups, led by industry mentors, to improve their resumes and cover letters, interviewing skills, networking abilities, project management, and ability to give and receive feedback. Objective is for students to be able to adapt and contribute effectively to their future employment organizations. A total of two units of credit is awarded for completion of the fall and subsequent spring term offerings. Application required; consult UPOP website for more information.","groups":[{"type":"Lab","options":[{"days":["M"],"start":"13:00","end":"14:00","room":"3-270"},{"days":["M"],"start":"15:00","end":"16:00","room":"4-237"},{"days":["T"],"start":"13:00","end":"14:00","room":"4-149"},{"days":["T"],"start":"15:00","end":"16:00","room":"3-370"},{"days":["F"],"start":"11:00","end":"12:00","room":"1-390"},{"days":["F"],"start":"13:00","end":"14:00","room":"1-190"}]}],"url":"http://student.mit.edu/catalog/mSWEa.html#SWE.017"},{"code":"WGS.101","title":"Introduction to Women's and Gender Studies","level":"U","description":"Drawing on multiple disciplines - such as literature, history, economics, psychology, philosophy, political science, anthropology, media studies and the arts - to examine cultural assumptions about sex, gender, and sexuality. Integrates analysis of current events through student presentations, aiming to increase awareness of contemporary and historical experiences of women, and of the ways sex and gender interact with race, class, nationality, and other social identities. Students are introduced to recent scholarship on gender and its implications for traditional disciplines.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"15:30","end":"17:00","room":"1-246"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.101"},{"code":"WGS.109","title":"Women and Global Activism in Media and Politics","level":"U","description":"An interdisciplinary subject that examines questions of feminism, international women's issues, and globalization through the study of novels, films, critical essays, painting and music. Considers how women redefine the notions of community and nation, how development affects their lives, and how access to the internet and to the production industry impacts women's lives. Primary topics of interest include transformations of traditional values, social change, gender role distribution, identity formation, migration flows, globalization and development, popular culture, urban life, cyber-culture, activism, and human rights. Limited to 25 when Writing Tutor is assigned to the class. Otherwise, limited to 18.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"56-180"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.109"},{"code":"WGS.110","title":"Sexual and Gender Identities in the Modern United States","level":"U","description":"Provides an introduction to the history of gender, sex, and sexuality in the modern United States, from the end of the 19th century to the present. Surveys historical approaches to the field, emphasizing the changing nature of sexual and gender identities over time. Traces attempts to control, construct, and contain sexual and gender identities. Examines the efforts of those who worked to resist, reject, and reform institutionalized heterosexuality and mainstream configurations of gendered power.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"13:00","end":"14:30","room":"1-134"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.110"},{"code":"WGS.111","title":"Gender and Media Studies","level":"U","description":"Examines representations of race, gender, and sexual identity in the media. Considers issues of authorship, spectatorship, and the ways in which various media (film, television, print journalism, advertising) enable, facilitate, and challenge these social constructions in society. Studies the impact of new media and digital media through analysis of gendered and racialized language and embodiment online in blogs and vlogs, avatars, and in the construction of cyberidentities. Provides introduction to feminist approaches to media studies by drawing from work in feminist film theory, cultural studies, gender and politics, and cyberfeminism.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"19:00","end":"20:30","room":"4-237"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.111"},{"code":"WGS.120","title":"Science in Action: Technologies and Controversies in Everyday Life","level":"U","description":"Explores how science and technology impact everyday life, through the lens of current controversies and debates. Students examine the role of scientific research, the tensions between human and technological boundaries, and how politics and culture shape technological practice. Subject materials draw from humanities and social science scholarship, documentaries, and other multimedia to explore science's dynamic and contested relationship with social life and cultural ideas. Students work to develop critical perspectives on how scientific practice intersects with society.","groups":[{"type":"Lecture","options":[{"days":["F"],"start":"13:00","end":"15:00","room":"4-163"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.120"},{"code":"WGS.130","title":"Afrofuturism, Magical Realism, and Other Otherwise Worlds","level":"U","description":"Examines Afrofuturism, magical realism, and other forms of the fantastic in literary texts, film, and other media. Through close reading and attention to historical, cultural, and sociopolitical context, students consider how these works reinterpret the past, diagnose modernity, and posit alternative futures. Particular attention given to the roles race, gender, class, and sexuality play within these radically imaginative worlds. Topics vary from term to term but might include work by Octavia Butler, Gabriel García Márquez, Samuel Delany, Toni Morrison, N.K. Jemisin, José María Arguedas, and Janelle Monáe. Limited to 18.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:30","end":"17:00","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.130"},{"code":"WGS.145","title":"Globalization:  The Good, the Bad and the In-Between","level":"U","description":"Examines the cultural paradoxes of contemporary globalization. Studies the cultural, artistic, social and political impact of globalization across international borders. Students analyze contending definitions of globalization and principal agents of change, and why some of them engender backlash; identify the agents, costs and benefits of global networks; and explore how world citizens preserve cultural specificity. Case studies on global health, human trafficking and labor migration illuminate the shaping influence of contemporary globalization on gender, race, ethnicity, and class. Develops cultural literacy through analysis of fiction and film. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"14N-325"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.145"},{"code":"WGS.225","title":"The Science of Race, Sex, and Gender","level":"U","description":"Examines the role of science and medicine in the origins and evolution of the concepts of race, sex, and gender from the 17th century to the present. Focus on how biological, anthropological, and medical concepts intersect with social, cultural, and political ideas about racial, sexual, and gender difference in the US and globally. Approach is historical and comparative across disciplines emphasizing the different modes of explanation and use of evidence in each field.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"10:30","end":"12:00","room":"26-139"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.225"},{"code":"WGS.230","title":"Representing Girlhood","level":"U","description":"Invites students to analyze cultural artifacts that represent girlhood from various eras and genres, including novels, children's literature, poetry, film, television, and popular music. Conceives girlhood in a broadly inclusive way, putting a range of materials — e.g., cultural artifacts that center Black, Jewish, Asian, and queer girls — in conversation with one another, by artists like Toni Morrison, Judy Blume, Andrea Wang, and Chappell Roan. Helps students build their oral presentation skills. Includes field trips to local museums or cultural events. Limited to 20.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"14N-325"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.230"},{"code":"WGS.231","title":"Writing about Race","level":"U","description":"The issue of race and racial identity have preoccupied many writers throughout the history of the US. Students read Jessica Abel, Diana Abu-Jaber, Lynda Barry, Felicia Luna Lemus, James McBride, Sigrid Nunez, Ruth Ozeki, Danzy Senna, Gloria Anzaldua, Judith Ortiz Cofer, Carmit Delman, Stefanie Dunning, Cherrie Moraga, Hiram Perez and others, and consider the story of race in its peculiarly American dimensions. The reading, along with the writing of members of the class, is the focus of class discussions. Oral presentations on subjects of individual interest are also part of the class activities. Students explore race and ethnicity in personal essays, pieces of cultural criticism or analysis, or (with permission of instructor) fiction. All written work is read and responded to in class workshops and subsequently revised. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"11:30","end":"13:00","room":"56-169"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.231"},{"code":"WGS.238","title":"Intersectional Feminist Memoir","level":"U","description":"Explores the memoir genre through a feminist intersectional lens, looking at the ways in which feminist writers ground personal experience within a complex understanding of race, gender, sexuality, class, ethnicity, immigration status/nationality, and dis/ablity. Gives particular attention to the relationships between the personal and the political; form and content; fact, truth, and imagination; self and community; trauma and healing; coming to voice and breaking silence. Readings include books by Audre Lorde, Janet Mock, Daisy Hernandez, Jessica Valenti, and Ariel Gore, and shorter pieces by Meena Alexander and Leah Lakshmi Piepzna-Samarasinha. Drawing on lessons taken from these works, students write a short memoir of their own.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"09:30","end":"11:00","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.238"},{"code":"WGS.250","title":"HIV/AIDS in American Culture","level":"U","description":"Examines cultural responses to HIV/AIDS in the US during the first fifteen years of the epidemic, prior to the advent of highly active antiretroviral therapy. Students consider how sexuality, race, gender, class, and geography shaped the experience of HIV/AIDS and the cultural production surrounding it, as well as the legacy of this cultural production as it pertains to the communities most at risk today. Materials include mainstream press coverage, film, theater, television, popular music, comic books, literature, and visual art.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"2-103"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.250"},{"code":"WGS.255","title":"Gender, Myth, and Magic","level":"U","description":"Explores ways contemporary writers re-imagine myth and fairy tales through lens of gender and sexuality. Examines how old stories can be retold to resonate with issues of power, violence, courage, resistance, identity, community, silence, and voice. Students complete writing project where they re-imagine a myth or fairy tale.","groups":[{"type":"Lecture","options":[{"days":["M","W"],"start":"10:00","end":"11:30","room":"4-253"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.255"},{"code":"WGS.258","title":"Children and Culture","level":"U","description":"Explores the relationship between children and the culture they inhabit in a particular time and place. Invites students to analyze in detail the image of childhood that emerges from many different media, including novels, children's literature, drama, film, television, dance, and popular song. Encourages students to take an interdisciplinary 'childhood studies' approach to youth culture that incorporates insights from literary and media studies, women's and gender studies, and the history and philosophy of childhood. Enrollment limited.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"15:00","end":"16:30","room":"56-180"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.258"},{"code":"WGS.266","title":"Womanhood, Gender, and Religion","level":"U","description":"Examines how religious traditions, theologies, and practices help produce and reproduce conceptions of womanhood and gendered bodies. Analyzes how religious traditions inform and direct shifting conceptions of gender in contemporary world. Studies religion and gender from top-down views through scripture, religious structures, theological debates, and myths of cosmological and human origins. Analyzes gendered experiences of religion including sexuality, menstruation, spirit possession, religious laws, and embodied expressions of faith. Explores questions of religious leadership, queering religion, sites of worship, and afterlife. Introductory study of religious, philosophical, and cultural traditions including: Judaism, Christianity, Islam, Buddhism, Hinduism, Confucianism, Western secularism, and Indigenous spiritual and religious practices. Assessments include a creative writing project, ethnographic interview, and book review. Enrollment limited to 50.","groups":[{"type":"Lecture","options":[{"days":["T","R"],"start":"13:00","end":"14:30","room":"66-148"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.266"},{"code":"WGS.277","title":"D-Lab: Gender and Development","level":"U","description":"Explores gender roles, illuminates the power dynamics and root causes of inequality, and provides a framework for understanding gender dynamics. Develops skills to conduct a gender analysis and integrate gender-sensitive strategies into large- and small-scale development solutions. Prompts critical discussion about social, economic, and political conditions that shape gender in development. Begins with exploration of international development in the post-colonial era, using a gender lens, then provides students with the tools to integrate gender-sensitive strategies into international development work, with a particular focus on launching, building and scaling women's ventures. Opportunities may be available for international fieldwork over IAP. Meets with 24.234 when offered concurrently. Students taking graduate version complete additional assignments. Limited to 12; must attend first class session.","groups":[{"type":"Lecture","options":[{"days":["W"],"start":"09:30","end":"12:30","room":"N51-310"}]}],"url":"http://student.mit.edu/catalog/mWGSa.html#WGS.277"}]);
